        res.animate([{ clipPath: "inset(-10px 0 -10px 100%)", opacity: 0 }, { clipPath: "inset(-10px 0 -10px 100%)", opacity: 1, offset: .01 }, { clipPath: "inset(-10px 0 -10px 0)", opacity: 1 }], Object.assign({}, o, { delay: 760 }));
