window.ZXR = {"l0003":[{"t":"Next-token odds","q":"The prompt is <code>The capital of France is</code>. Will <code> Paris</code> be the model's most likely next token?","a":"No. <code> the</code> leads with 8.5%, and <code> Paris</code> is fifth at 3.2%. The model gives odds for every one of its 50,257 tokens. It does not look up an answer.","h":"1m4xdkt"},{"t":"Eight greedy steps","q":"The loop always takes the single most likely token, eight times. Does the sentence ever name the capital?","a":"No. It writes <code>the capital of the French Republic, and</code>. Each step picks one token, adds it and asks again, and the most likely next word is not the same thing as the right answer.","h":"1hxqioz"},{"t":"A base model","q":"This is a base model, given a request for an email. Will it write the email?","a":"No. It continues the text with a line of dialogue. A model that predicts text is not yet an assistant: it has to be trained to follow instructions.","h":"e3s0f5"},{"t":"Retrieval","q":"What does the prompt contain besides the question?","a":"The note that <code>retrieve</code> found, pasted in above the question. Retrieval means finding the relevant text yourself and putting it into the prompt.","h":"om9fw5"}],"l2101":[{"t":"Arithmetic","q":"What does <code>0.1 + 0.2</code> print?","a":"<code>0.30000000000000004</code>, not <code>0.3</code>. Most decimals cannot be stored exactly in binary, so round when you show them. <code>/</code> gives a decimal, <code>//</code> the whole part and <code>%</code> the remainder.","h":"9d3uwx"},{"t":"Strings","q":"<code>name</code> is <code>\"Asha\"</code>. What does <code>name[0], name[-1], name[1:3]</code> give?","a":"<code>A a sh</code>. Positions start at 0, <code>-1</code> is the last character, and the slice <code>1:3</code> stops before position 3.","h":"1i0qsel"},{"t":"Converting types","q":"<code>typed</code> is the string <code>\"42\"</code>. What do <code>typed + \"1\"</code> and <code>int(typed) + 1</code> print?","a":"<code>421</code> and <code>43</code>. Two strings are joined, and a number is added only after you convert. <code>int(4.99)</code> is 4, because it cuts off and does not round.","h":"h0zbjj"}],"l2102":[{"t":"Lists","q":"After <code>append</code>, <code>insert(1, \"milk\")</code>, <code>remove(\"soap\")</code> and <code>pop()</code>, what is left in <code>cart</code>?","a":"<code>['tea', 'milk', 'rice']</code>, and <code>pop()</code> handed back <code>pens</code>. A list keeps its order, and each of these methods changes the list in place.","h":"1yopuf4"},{"t":"Sets","q":"The set is written with four items, two of them <code>\"urgent\"</code>. What is its length?","a":"3. A set keeps no duplicates and no order, which is why <code>sorted(tags)</code> is used to print it.","h":"iwzd5i"},{"t":"if, elif, else","q":"<code>cart_total</code> is 420. Which branch runs, and what is the amount to pay?","a":"The <code>elif</code> branch: 420 is below 499 but at least 300, so the fee is 20 and the total is 440. Python takes the first branch whose test is true and skips the rest.","h":"1awnaoc"},{"t":"Comprehensions","q":"What does the comprehension with <code>if p &lt; 100</code> keep?","a":"<code>[89, 35]</code>. A comprehension builds a collection in one line: an expression, a loop and an optional filter. The loop above it and the one-line version give the same <code>with_tax</code> list.","h":"1rcaze2"}],"l2103":[{"t":"Calling a function","q":"What do the three calls print?","a":"998, 898 and 247. The first uses the default discount of 0. Arguments given by name can come in any order.","h":"1cc5cm4"},{"t":"Local variables","q":"<code>tax</code> is created inside <code>add_tax</code>. What happens when the code prints <code>tax</code> afterwards?","a":"A <code>NameError</code>. A function can read a global such as <code>rate</code>, but variables created inside it vanish when it returns.","h":"jlffzu"},{"t":"Functions as values","q":"<code>sorted(orders)</code> and <code>sorted(orders, key=lambda o: o[1])</code>: what does each sort by?","a":"The first sorts by the ID and the second by the amount. <code>key</code> takes a function, because functions are values you can pass around or store in a dictionary, as <code>STYLES</code> does.","h":"ai0m9g"},{"t":"try and except","q":"What does <code>parse_qty(\"three\")</code> return?","a":"1, after printing a message. The function catches the error and falls back to a default. The last line shows the other choice: rejecting a bad value such as -2 with a clear message.","h":"1l3ynjt"}],"l2104":[{"t":"Appending to a file","q":"The log is opened with mode <code>\"a\"</code>, not <code>\"w\"</code>. How many log lines do you expect at the end?","a":"Two: <code>viewed</code>, then <code>refunded</code>. Mode <code>\"a\"</code> appends to the file, where <code>\"w\"</code> would overwrite it.","h":"vdo5k8"},{"t":"A request without a key","q":"This request is sent without the API key. What comes back?","a":"Status 401 and an error body. The request itself does not fail: you get a normal response and must check its status. The last line shows the same failure raised as an <code>HTTPError</code>.","h":"3xuoeg"}],"l2105":[{"t":"Everything is an object","q":"What do the two <code>isinstance</code> checks print?","a":"<code>True False</code>. <code>name</code> is an object of class <code>str</code> and <code>cart</code> is an object of class <code>list</code>. A value's methods come from its class.","h":"lgng9v"},{"t":"Two objects, one class","q":"Two carts are made from the same class. Does adding items to Asha's cart change Ravi's?","a":"No. Ravi's cart prints 0 items and a total of 0. Each object keeps its own data, and the class only describes the shape.","h":"tnfq8v"},{"t":"Printing your own object","q":"What does <code>print(cart)</code> show for an object of your own class?","a":"<code>Cart('Asha', 2 lines, total=588.0)</code>, because the class says how it prints. <code>len(cart)</code> works for the same reason: the class says what its length is.","h":"cysxpy"},{"t":"Exploring an object","q":"How many days are there from 9 November 2026 to 25 December 2026?","a":"46. Subtracting two dates gives an object with a <code>days</code> attribute. <code>type</code> and <code>dir</code> are how you explore an object you have not met before.","h":"1cbezmn"}],"l2106":[{"t":"Shape","q":"What are the shape and the number of dimensions of <code>sales</code>?","a":"<code>(3, 4)</code> and 2: three rows (days) and four columns (products), 12 values in all. <code>prices</code> has one dimension and shape <code>(4,)</code>.","h":"m2ocmk"},{"t":"Masks","q":"<code>busy = sales &gt; 2</code>. What does <code>sales[busy]</code> return?","a":"<code>[3 5 4 6 3]</code>: only the values where the mask is true, as a flat array. The same idea filters <code>prices</code> to those under 100 in one step.","h":"1jiaurc","tail":2},{"t":"Axes","q":"<code>sales.sum(axis=0)</code> or <code>sales.sum(axis=1)</code>: which gives one total per product?","a":"<code>axis=0</code>. It adds down the rows and leaves one number per column: <code>[10 5 7 5]</code>. <code>axis=1</code> adds across and gives one per day: <code>[10 7 10]</code>.","h":"reo4r4"},{"t":"Reshape","q":"What shape does <code>a.reshape(-1, 3)</code> give for six values?","a":"<code>(2, 3)</code>. <code>-1</code> asks NumPy to work that dimension out. <code>.T</code> swaps rows and columns, so the <code>(3, 4)</code> sales table becomes <code>(4, 3)</code>.","h":"7rdooe"}],"l2107":[{"t":"loc and iloc","q":"<code>df.loc[1, \"city\"]</code> and <code>df.iloc[0, 2]</code>: what does each return?","a":"<code>Delhi</code> and <code>540.0</code>. <code>loc</code> selects by labels and <code>iloc</code> by positions. A list of names inside the brackets selects several columns.","h":"b4r9f0"},{"t":"Missing values","q":"One amount is missing. Is the mean higher when you ignore it or when you count it as 0?","a":"Higher when ignored: 454.6 against 378.83. pandas skips missing values by default, and filling with 0 is a decision that changes the answer.","h":"zk3bxt"},{"t":"A left join","q":"<code>customers</code> has a row for SK-7, which is not in <code>df</code>. What does a left join keep?","a":"Every order in <code>df</code>, with the customer added where one is known. SK-7 is dropped, because a left join keeps the rows of the left table.","h":"w1sh71"}],"l2108":[{"t":"Annotated","q":"What does <code>Log.__metadata__</code> hold?","a":"The function <code>operator.add</code>. <code>Annotated</code> attaches extra information to a type, and a library can read it. LangGraph reads this to know how to merge updates.","h":"1enp009"},{"t":"JSON","q":"Python's <code>False</code> and <code>None</code>: how do they appear in the JSON text?","a":"As <code>false</code> and <code>null</code>. <code>json.dumps</code> turns a dict into text and <code>json.loads</code> turns it back. Pydantic then writes the JSON Schema of a class for you.","h":"15wx4hd"},{"t":"Decorators","q":"What does <code>apply_twice(lambda n: n * 10, 3)</code> return?","a":"300: the function is applied to 3, then to the result. The decorated <code>get_status</code> prints its timing line and still has its own name and docstring.","h":"1wslzf"},{"t":"Generators","q":"After two <code>next</code> calls, what do the two <code>list(pieces)</code> calls give?","a":"The remaining four words, and then an empty list. A generator is used up once it has been read.","h":"sfqxbu"}],"l2201":[{"t":"Adding and scaling","q":"<code>mix</code> is the average of chips and chocolate. What kind of snack does it describe?","a":"<code>[0.5 0.5 0.3]</code>: an in-between, sweet-and-salty one. Adding vectors adds matching components, and scaling multiplies every component.","h":"psj52u"},{"t":"Distance","q":"Which snack is closest to masala chips?","a":"Namkeen mix, at distance 0.173. Chocolate is farthest at 1.281. Distance is the length of the difference between two vectors.","h":"kjbya"},{"t":"Cosine similarity","q":"<code>mild_chips</code> has the same taste profile at half the intensity. What is its cosine similarity to chips?","a":"1.000, although the distance is 0.543. Cosine compares direction and ignores length.","h":"1amspiy"},{"t":"Many dimensions","q":"In 768 dimensions, how similar are two random vectors?","a":"Hardly at all: the typical cosine is 0.029, against 0.644 in two dimensions. In many dimensions random vectors are almost at right angles, so a high similarity means something.","h":"1shlggh"}],"l2202":[{"t":"Rows and columns","q":"What is <code>recipes[:, 0]</code>?","a":"<code>[50 10 150]</code>: column 0, everything one tea needs. A matrix is a table of numbers, indexed by row and then by column.","h":"1w3t95o"},{"t":"Matrix times vector","q":"Four teas and two coffees. Do the two views give the same totals?","a":"Yes, <code>[360 50 840]</code> each time. A matrix times a vector is a dot product per row, and equally a mix of the columns. <code>@</code> does it in one operation.","h":"3yqy4l"},{"t":"Matrix times matrix","q":"<code>recipes</code> is (3, 2) and <code>week</code> is (2, 3). What shape is <code>recipes @ week</code>?","a":"(3, 3): ingredients by days. The inner sizes must match and they disappear. The outer sizes remain.","h":"b8exlf"},{"t":"A layer","q":"A batch of 4 inputs goes through a layer with 2 outputs. What shape comes out?","a":"(4, 2): two outputs for each of the four inputs. A neural network layer is a matrix multiplication plus a bias, and the first row matches the single input computed above it.","h":"1eqh4cs"}],"l2203":[{"t":"A distribution","q":"90, 60, 30 and 20 tickets. What must the four probabilities add up to?","a":"1.0. Dividing each count by the total turns counts into a distribution.","h":"1snek3n"},{"t":"Conditional probability","q":"After the word <code>order</code>, which words can follow in this corpus?","a":"Only <code>is</code>, with probability 1.0. After <code>is</code> there are four options. The probability of the next word depends on what came before.","h":"1rw6q3i"},{"t":"Softmax and temperature","q":"What does temperature 0.5 do to the top probability, compared with 1.0?","a":"It raises it from 0.514 to 0.761. A low temperature sharpens the distribution and a high one flattens it. Adding the same number to every score changes nothing.","h":"11cgzfg"},{"t":"Log-probabilities","q":"What is 0.2 multiplied by itself 1,000 times, on a computer?","a":"Exactly 0.0: the product underflows. The sum of the logs, -1609.44, is a normal-sized number, which is why models work with log-probabilities.","h":"1i0ztfb"}],"l2204":[{"t":"A slope","q":"At which <code>w</code> is the slope zero?","a":"At <code>w = 3</code>, the bottom of the curve, where the loss is 1.00. The sign of the slope tells you which way to move: a negative slope means increase <code>w</code>.","h":"1opqldl"},{"t":"The chain rule","q":"The local slopes are 3, 2u and 1, at <code>w = 1</code>. What is the slope of the whole chain?","a":"18. With <code>u = 3</code> the local slopes are 3, 6 and 1, and they multiply. Nudging the whole function gives the same number.","h":"10il6tc"},{"t":"The gradient","q":"At <code>w = (0, 0)</code> the gradient is <code>[-6, 4]</code>. Which way should each coordinate move to lower the loss?","a":"Against the gradient: the first up and the second down, toward the lowest point at (3, -1). The gradient is one slope per input.","h":"12p3fmf"},{"t":"Gradient descent","q":"Learning rates 0.01, 0.1, 0.45 and 0.55, fifty steps each. Which one fails?","a":"0.55: the second coordinate blows up to about 9,099. 0.01 is too slow and has not arrived. Too large a step overshoots further every time.","h":"176208p"}],"l2301":[{"t":"Rules by hand","q":"A hand-written rule flags urgent tickets. Does it flag the parcel that is leaking chemicals?","a":"No. It prints <code>False</code> for that ticket, and <code>True</code> for a question about an urgent-delivery option. Hand-written rules match words, not meaning.","h":"jxesj2"},{"t":"Learning a rule","q":"Thresholds of 3, 6, 9 and 12 km are tried. Which makes the fewest mistakes?","a":"9, with 2 mistakes. The program tries every threshold and keeps the best. Finding the rule from examples is what learning means.","h":"7otiun"},{"t":"Using the rule","q":"With the learned threshold of 9, what does the rule say for 9.5 km?","a":"<code>late</code>. Nobody told the rule about 9.5 km: it applies what it learned to a new case.","h":"1kevj46"},{"t":"Text labels itself","q":"How many training examples does one six-word sentence give?","a":"Five. Each beginning of the sentence is an input and the next word is its answer, so text needs nobody to label it.","h":"plhzor"}],"l2302":[{"t":"The model","q":"With <code>w = 2</code> and <code>b = 15</code>, what does the model predict for 10 km?","a":"35.0 minutes: 2 × 10 + 15. The model is one line of arithmetic. Learning means finding good values for <code>w</code> and <code>b</code>.","h":"rz9nd1"},{"t":"The loss","q":"Which guess has the lower MSE?","a":"<code>w=2, b=15</code>, at 18.2 against 73.35. The loss is one number for how wrong the model is, so two guesses can be compared.","h":"wndi8c"},{"t":"After scaling","q":"After scaling the feature, what line do 100 steps of gradient descent find, in km units?","a":"2.5 minutes per km plus 8.756 minutes. Scaling changes the numbers that training sees, not the line it finds.","h":"108a26o"},{"t":"scikit-learn","q":"scikit-learn fits the same data. Does it find the same <code>w</code> and <code>b</code>?","a":"Yes: 2.5 and 8.756. The library does in two lines what you built by hand, and now you know what <code>fit</code> does.","h":"y0pq5q"}],"l2303":[{"t":"The sigmoid","q":"What probability does the sigmoid give for a score of 0?","a":"0.500. Large negative scores approach 0 and large positive ones approach 1, so any score becomes a probability.","h":"2ywk51"},{"t":"Cross-entropy","q":"The delivery really was late. What is the loss when the model said 0.01?","a":"4.605, against 0.010 when it said 0.99. Cross-entropy punishes a confident wrong answer far more than an unsure one.","h":"qkv8x4"},{"t":"Training","q":"After training, at what distance does the probability of being late cross 0.5?","a":"9.6 km. The loss falls from 0.6823 to 0.4376 as <code>w</code> and <code>b</code> move, and the trained model gives 0.07 at 4 km and 0.75 at 12 km.","h":"e5s667"},{"t":"Two features","q":"The distance is 8 km both times. Does rain change the predicted class?","a":"Yes: on time when dry (0.26 late) and late when raining (0.6). The model draws the line at 10.7 km when dry and 6.9 km in rain.","h":"pbkh3l"}],"l2304":[{"t":"Accuracy","q":"9 of 24 tickets are urgent, the model flags 10, and accuracy is 0.875. Does that say which mistakes it made?","a":"No. Accuracy counts all mistakes alike. The next step splits them into missed urgent tickets and false alarms.","h":"1rg1e7b"},{"t":"Precision and recall","q":"TP 8, FN 1, FP 2. What are precision and recall?","a":"Precision 0.800 (8 of the 10 flagged were urgent) and recall 0.889 (8 of the 9 urgent were flagged). F1 combines the two.","h":"16kyoug"},{"t":"Choosing the threshold","q":"A miss costs 10 and a false alarm costs 1. Is 0.5 the cheapest threshold?","a":"No. 0.4 costs 3 and 0.5 costs 12. When one mistake is far worse than the other, move the threshold.","h":"1t3lypv"},{"t":"ROC AUC","q":"Does the hand count of correctly ranked pairs match scikit-learn's ROC AUC?","a":"Yes, 0.9444 both ways. ROC AUC is the fraction of (urgent, not urgent) pairs the scores rank correctly, with no threshold involved.","h":"9pcqr8"}],"l2305":[{"t":"Overfitting","q":"As the degree rises, training error keeps falling. What does validation error do?","a":"It falls to 0.0172 at degree 4, then rises, and at degree 11 it explodes while training error is 0.0000. The model has memorised the training points.","h":"1wx4x30"},{"t":"A penalty","q":"A degree-9 model with no penalty has a largest weight of 264.61. What does a small ridge penalty do?","a":"It shrinks the largest weight to 6.15 and cuts validation error from 0.3070 to 0.0247. Too large a penalty (alpha 10) makes both errors worse again.","h":"d5pfyx"},{"t":"Cross-validation","q":"Five folds give five scores. How far apart are they?","a":"From 0.872 to 0.942, with a mean of 0.915 and a spread of 0.027. One split can be lucky or unlucky. Five give a steadier estimate.","h":"1mtj3zk"}],"l2306":[{"t":"A decision tree","q":"What is the first question the tree asks?","a":"Whether the distance is at most 9.25 km, and then whether it is raining. A decision tree is a set of learned if-then rules that you can read.","h":"8brr3g"},{"t":"Nearest neighbours","q":"The three nearest neighbours of chikki are all sweet. What does the model predict?","a":"<code>sweet</code>. Nearest neighbours looks up the closest known examples and takes their vote.","h":"prcz9e"},{"t":"How many clusters","q":"Inertia falls as k grows. Where does the improvement slow down?","a":"After k = 3: 300.0, 95.0, 24.5, and then only 17.0. That bend suggests three groups in the data.","h":"1hmzl6e"},{"t":"Learning from rewards","q":"Three routes with unknown on-time rates. Which one does the learner end up using most?","a":"The second, 855 times out of 1,000, because its estimate (0.758) is the highest. It still tried the others now and then, which is how it found out.","h":"12yunlt"}],"l2401":[{"t":"One neuron","q":"Inputs 7.5, 3.0 and 1.0, weights 0.4, 0.8 and 2.0, bias -3. What is <code>z</code>?","a":"4.4: 3.0 + 2.4 + 2.0 - 3.0. ReLU leaves a positive number unchanged, so the neuron outputs 4.4.","h":"z63x8t"},{"t":"A layer","q":"What does ReLU do to the negative entries of <code>Z</code>?","a":"It sets them to 0 and leaves the positive ones alone. A layer is one matrix multiplication for the whole batch, then the activation.","h":"1margk2","o":[2,10]},{"t":"XOR","q":"Does the output match XOR for the four inputs?","a":"Yes: <code>[0 1 1 0]</code>. The second hidden neuron fires only when both inputs are on, and the output subtracts it twice. One straight line cannot do this. Two layers can.","h":"12lf5tj"},{"t":"Why activations matter","q":"Eight hidden units with no activation: are they better than logistic regression?","a":"No. Both score 0.645, the same as always guessing 'outside'. Without an activation, layers collapse into one straight line. With ReLU, 4 units reach 0.940.","h":"1uyf7gz"}],"l2402":[{"t":"Backward","q":"<code>L = (a*b + c) * f</code>. What is the gradient of <code>L</code> with respect to <code>a</code>?","a":"6: <code>f</code> times <code>b</code>, which is -3 × -2. <code>backward()</code> walks the graph from <code>L</code> and gives every value its slope.","h":"1m1u8k1"},{"t":"Gradients add","q":"<code>y = x*x + x*3</code> at <code>x = 2</code>. What gradient does <code>x</code> get?","a":"7, which is 2x + 3. <code>x</code> is used along several paths, and the gradients from each path add up.","h":"3yptpf"},{"t":"Counting parameters","q":"A network with layers of 3, 4, 4 and 1. How many parameters does it have?","a":"41: (3×4 + 4) + (4×4 + 4) + (4×1 + 1). Each layer has a weight per connection and a bias per neuron.","h":"cdppvq"},{"t":"With matrices","q":"The same training written with matrices. What happens to validation accuracy over 2,000 steps?","a":"It climbs from 64.5% to 98.0% while the training loss falls from 0.659 to 0.036.","h":"1ivonq3"}],"l2403":[{"t":"nn.Linear","q":"<code>nn.Linear(3, 2)</code>: what shape is its weight?","a":"<code>[2, 3]</code>: one row of three weights per output. The result carries a <code>grad_fn</code>, which is PyTorch remembering how it was computed.","h":"14ore9b"},{"t":"Mini-batches","q":"1,437 training images and a batch size of 64. What shape is one batch?","a":"<code>[64, 64]</code>: 64 images of 64 pixels each. The loader shuffles the data and hands it out in mini-batches.","h":"1vsgi0r"},{"t":"The training loop","q":"What happens to validation loss across 30 epochs?","a":"It falls from 2.0229 to 0.1301 and accuracy rises to 0.969. The loop remembers the best epoch, here the last one.","h":"glizty"}],"l2404":[{"t":"Initialisation","q":"Twenty layers with weights that are too large. What happens to the signal?","a":"It explodes: the spread is 9.35 after one layer and 1.69e+05 after five. Too small and it vanishes. He initialisation keeps it near 1.","h":"xqwxit"},{"t":"A deep plain network","q":"A plain 20-layer network: how large is the gradient at layer 1?","a":"2.7e-18, effectively zero, against 0.047 at layer 20. The first layers cannot learn, and accuracy stays at 0.075.","h":"1649ib8"},{"t":"Optimisers","q":"SGD with a learning rate of 0.039 works. What about 0.041?","a":"It diverges to 4.32e+05. Plain SGD is limited by the steepest direction. Momentum and Adam reach a loss near zero.","h":"ebjkh3"},{"t":"A schedule","q":"The schedule warms up for 2,000 steps. What is the learning rate at step 500?","a":"7.50e-05, a quarter of the peak. It reaches 3.00e-04 at step 2,000 and decays along a cosine to 3.00e-05.","h":"10n5030"}],"l2405":[{"t":"One-hot vectors","q":"With one-hot vectors, how similar are bread and butter, compared with bread and sponge?","a":"Both 0.0. A one-hot vector makes every product equally different from every other, so it carries no idea of similarity.","h":"1otzbxu"},{"t":"A lookup table","q":"Is looking up the row for <code>tea</code> the same as multiplying a one-hot vector by the table?","a":"Yes, it prints <code>True</code>. An embedding is a lookup table: one learned row per item, here 15 products with 4 numbers each.","h":"o9phj9"},{"t":"Learned from baskets","q":"After training on shopping baskets, which products end up nearest to <code>diapers</code>?","a":"Baby wipes (1.0) and baby food (0.99). Products bought together get similar vectors, and nobody told the model what a baby product is.","h":"50bdfp"}],"l2406":[{"t":"Counting arithmetic","q":"A model has 8 billion parameters. About how many operations does one generated token cost?","a":"About 1.6e+10, roughly two per parameter. One 768 × 3072 layer alone needs 4,718,592 for a single token.","h":"1db0rgk"},{"t":"Loops against NumPy","q":"The same matrix product as a Python loop and in NumPy. How much faster is NumPy?","a":"More than 100 times, with the same answer. The arithmetic is identical. Doing many multiplications at once is the idea GPUs take further.","h":"1mapal5"},{"t":"Quantisation","q":"Weights stored in 8 bits, or in 4 bits with one scale: how large is the error?","a":"1.0% of a typical weight at 8 bits and 18.3% at 4 bits. A separate scale per 32 weights brings 4-bit down to 10.2%.","h":"e15s8k"},{"t":"Memory","q":"An 8B model needs 32 GB in float32. What does it need in 4-bit, and for training with AdamW?","a":"4 GB in 4-bit and 128 GB to train. Memory is usually what decides which model you can run.","h":"12n24mj"}],"l2407":[{"t":"An image is numbers","q":"What does the computer receive for this handwritten 7?","a":"An 8 × 8 grid of brightness numbers. The right-hand side draws the same numbers as characters so that you can see the 7.","h":"90jmyt"},{"t":"Convolution by hand","q":"A 3 × 3 filter slides over an 8 × 8 image. What shape is the output?","a":"6 × 6, because a 3 × 3 window fits in 6 positions across an 8-pixel row. Large positive numbers mark where the stroke begins as you move right.","h":"1wvs9vi"},{"t":"Two networks","q":"Which has more parameters, the CNN or the MLP?","a":"The MLP: 9,930 against 5,130. A convolution reuses the same small filter everywhere, so it needs fewer weights.","h":"9ljfei","tail":1},{"t":"Move the digit","q":"Both models score 99.0% on centred digits. What happens when the digit moves 2 pixels right?","a":"The MLP falls to 15.1% and the CNN holds 95.0%. The MLP learned which pixel is usually bright. The CNN learned shapes wherever they are.","h":"1lbhzrz"}],"l2501":[{"t":"Stop words","q":"After removing stop words, which word is most common in the tickets?","a":"<code>order</code>, 4 times, then <code>refund</code>. Removing words such as <code>is</code> and <code>my</code> leaves the ones that carry the topic.","h":"1a67dv5"},{"t":"Patterns","q":"Which order IDs does the pattern <code>SK-\\d{5}</code> find?","a":"<code>SK-48213</code> and <code>SK-50017</code>. Rules work well when the thing has a fixed shape, such as an ID, an amount or a date.","h":"1q7u9a8"},{"t":"Where rules fail","q":"A keyword rule reads <code>No need for a refund, the replacement was fine</code>. What does it answer?","a":"<code>refund</code>, which is wrong. It also answers <code>unknown</code> for a smashed box. Rules match words and miss meaning, which is why language is hard.","h":"1iwn4r0"}],"l2502":[{"t":"Bytes","q":"<code>café</code> has 4 characters. How many bytes?","a":"5: the <code>é</code> takes two bytes. The Hindi word takes 18 bytes for 6 characters, and the emoji 4 bytes for one.","h":"1c7wc7c"},{"t":"Byte-pair encoding","q":"Byte-pair encoding merges the most frequent pair first. Which pair is it here?","a":"<code>t</code> + <code>h</code>, seen 18 times, then <code>th</code> + <code>e</code>. Each merge makes the text shorter: 229 tokens after the first merge and 96 after thirty.","h":"p6gvq4"},{"t":"A real tokeniser","q":"How many tokens is <code>Where is my order?</code> in the o200k_base tokeniser?","a":"Five: <code>Where</code>, <code> is</code>, <code> my</code>, <code> order</code> and <code>?</code>. The space belongs to the word that follows it.","h":"5peqc6"},{"t":"Tokenisers differ","q":"Does every tokeniser split <code>unbelievably</code> the same way?","a":"No. cl100k_base splits it into <code> unbelie</code> and <code>vably</code>, and the other two keep it whole. Open the full output to see how much more the Hindi sentence costs.","h":"1gtjglo"}],"l2503":[{"t":"A bag of words","q":"The ticket says <code>refund</code> twice. What does the bag of words record?","a":"<code>'refund': 2</code>, and 1 for each other word. Word order is thrown away. Most of the matrix is zeros: 2,010 non-zero entries of 62,208.","h":"6xh9jg"},{"t":"Where counting fails","q":"The classifier reads <code>no need for a refund, the replacement was fine</code>. What does it predict?","a":"<code>refund</code>, with 0.86 confidence. Counting words cannot see <code>no need for</code>. It is also unsure about the wrong address (0.49).","h":"1et00ym"}],"l2504":[{"t":"The company words keep","q":"Judged by their neighbouring words, how similar are <code>coffee</code> and <code>tea</code>? And <code>tea</code> and <code>friday</code>?","a":"1.00 and 0.00. Words used in the same contexts get the same row of counts, and that alone captures some meaning.","h":"m73iv1"},{"t":"GPT-2's embeddings","q":"In GPT-2's embedding table, which tokens are nearest to <code> Monday</code>?","a":"The other days: <code> Tuesday</code> 0.89, <code> Thursday</code> 0.85. Nearest to <code> seven</code> are other numbers. The table has 50,257 rows of 768 numbers each.","h":"9zo6cg"},{"t":"What embeddings absorb","q":"Along the direction from <code> she</code> to <code> he</code>, where does <code> nurse</code> fall?","a":"At -0.170, the furthest toward <code> she</code> of the eight. <code> engineer</code> is nearest zero at -0.014. Embeddings absorb the patterns of the text they were trained on, including its biases.","h":"ycrbvb"}],"l2505":[{"t":"Counting what comes next","q":"In Shakespeare, what follows the letter <code>q</code>?","a":"<code>u</code>, every one of 563 times. After <code>t</code> the most likely is <code>h</code> at 0.341. A bigram model is a table of these counts.","h":"1dmk6cz"},{"t":"Perplexity","q":"A uniform guess over 65 characters has perplexity 65. What does the bigram model reach?","a":"11.99, with a loss of 2.484. Perplexity is roughly how many characters the model is still choosing between.","h":"int5x3"},{"t":"Longer contexts","q":"Longer contexts help at first. At what n does validation loss stop improving?","a":"At n = 4 (1.784). By n = 7 it is back to 2.443, because most long contexts in new text were never seen in training. Counting does not generalise.","h":"1bgw0v8"}],"l2506":[{"t":"A neural language model","q":"Before training the loss is 4.097. Where does it get to after 4,000 steps?","a":"1.859. It starts near the uniform guess of 4.174 and falls as the network learns which characters follow which.","h":"18og88v"},{"t":"A recurrent network","q":"The RNN reads <code>to be</code> one character at a time. What changes at each step?","a":"The hidden state: four numbers recomputed from the new character and the old state. That vector is the network's only memory of what it has read.","h":"shdlb9"},{"t":"An LSTM","q":"The LSTM has 315,745 parameters. What validation loss does it reach in 1,000 steps?","a":"1.635, better than the 1.859 of the fixed-window network in Step 2.","h":"8nvnu6"}],"l2507":[{"t":"Attention by hand","q":"The four scores are 0.38, 2.08, 0.84 and 0.54. Which word gets the most attention weight?","a":"<code>is</code>, with 0.59. Softmax turns the scores into weights that add up to 1. The context vector is the weighted average of the states, so it lands closest to the state for <code>is</code>.","h":"hrwm3h"},{"t":"With and without","q":"Reversing 12 letters, with and without attention. How many whole strings does each model get right?","a":"4.6% without and 90.6% with. Without attention the whole input has to pass through one vector.","h":"1sb7230"},{"t":"Where it looks","q":"The trained model reverses <code>deliverances</code>. Which input position does the first output step attend to?","a":"Position 11, the last letter, with weight 1. Each later step looks one position earlier. The model learned where to look.","h":"ocyizh"}],"l2601":[{"t":"Attention weights","q":"Each row of attention weights comes from a softmax. What does a row add up to?","a":"1. The row for <code>parcel</code> is 0.47, 0.16, 0.20, 0.17. The output for each token is the average of the value vectors, weighted by its row.","h":"6z8t9o"},{"t":"Why divide by √d","q":"Raw dot products of 512-dimensional vectors have a spread of 22.59. What is it after dividing by √d?","a":"1.00, the same as for d = 4. Without the division, softmax puts all its weight on one token: <code>[1., 0., 0., 0.]</code>.","h":"75yyp1"},{"t":"A trained head","q":"In one head of GPT-2, which token does <code> it</code> attend to most?","a":"<code> suitcase</code>, with 0.65, far ahead of <code> trophy</code> at 0.07. This is one of 144 heads (12 layers of 12), each with its own pattern.","h":"19xz3uh"}],"l2602":[{"t":"The causal mask","q":"The causal mask hides the future. After masking, does each row of weights still add up to 1?","a":"Yes. Hidden positions get zero weight, and softmax shares the weight among the tokens that remain.","h":"1npmnp7"},{"t":"Many heads","q":"Multi-head attention takes a (2, 10, 768) tensor. What shape comes out?","a":"The same, (2, 10, 768). The heads work side by side and their results are joined back to the original width, using 2,362,368 parameters.","h":"3m2wxt"},{"t":"The cost of length","q":"Going from 8,000 to 32,000 tokens multiplies the length by 4. What happens to the attention scores?","a":"They grow 16 times, from 6.55e+10 to 1.05e+12 entries. Attention compares every pair of tokens, so its cost grows with the square of the length.","h":"g6ru5s"}],"l2603":[{"t":"No sense of order","q":"Shuffle the input tokens. What happens to attention's output?","a":"It is shuffled the same way and nothing else changes. Attention on its own cannot see word order.","h":"t86vkk"},{"t":"Position embeddings","q":"The same token appears twice. Are its two vectors still equal after position embeddings are added?","a":"No. Before, they are identical. After adding position 0 and position 1 they differ, and that is how the model can use order.","h":"fev2vu"},{"t":"A complete GPT","q":"How many parameters does this GPT have?","a":"124,439,808, the size of GPT-2 small.","h":"1p286tc"},{"t":"The real weights","q":"After loading GPT-2's real weights into your own code, do the outputs match the official model?","a":"Yes: the same logits, and the same top tokens as in Lesson 0.3, with <code> the</code> at 0.085 and <code> Paris</code> at 0.032.","h":"i4toxh"}],"l2604":[{"t":"Check the first loss","q":"Before any training, what should the loss be for 65 characters?","a":"About 4.174, a uniform guess. The model starts at 4.241, so the initialisation is sound. Check this number before you train.","h":"1k3fyzk"},{"t":"Train","q":"After 2,000 steps, where is the validation loss?","a":"1.618, down from 2.056 at step 400. Training loss and validation loss fall together.","h":"nxw8ef"},{"t":"Generate","q":"What does a model at a loss of 1.6 write?","a":"Text shaped like Shakespeare: a speaker name, line breaks, mostly real words, and no meaning. It learned spelling and form from characters alone.","h":"16yrxrj"}],"l2605":[{"t":"Next-token probabilities","q":"The model predicts the next token. Does its top choice get most of the probability?","a":"No. <code> refund</code> gets 0.357. The top 8 tokens cover 59% together, and the other 50,249 share the rest.","h":"1qfizv"},{"t":"Greedy decoding","q":"Greedy decoding always takes the most likely token. Does it write a good letter?","a":"No. After one sensible sentence it drifts into web-page boilerplate. Always taking the top token is not the same as writing well.","h":"ecjko3"},{"t":"Sampling","q":"Three seeds with temperature 0.8 and top-p 0.9. Are the three continuations the same?","a":"No. They start alike and then differ. Sampling picks among the likely tokens, so each run can take another path.","h":"148fuk3"},{"t":"The KV cache","q":"For 1,000 new tokens, how many token positions are processed without the KV cache?","a":"500,500, against 1,000 with it. The cache keeps the keys and values of earlier tokens so that they are not recomputed.","h":"1n1way5"}],"l2606":[{"t":"A masked model","q":"A masked language model fills the gap in <code>The parcel was [MASK] because of the heavy rain.</code> What is its top guess?","a":"<code>flooded</code>, at 0.378. An encoder reads the words on both sides of the gap.","h":"yisk6t"},{"t":"Contextual embeddings","q":"Is the vector for <code>bank</code> the same in a sentence about a loan and one about a river?","a":"No. The two money senses are close (0.83), and each is further from the river sense (0.60 and 0.58). A word's vector depends on its sentence.","h":"13hsnoq"},{"t":"Sentence embeddings","q":"How similar are <code>parcel never arrived</code> and <code>package not delivered</code>, which share no words?","a":"0.68, against 0.15 for <code>reset my password</code>. A sentence embedding compares meaning, not words.","h":"1eo5ikb"},{"t":"Search by meaning","q":"The query <code>the parcel came broken</code> shares no words with the FAQ about damaged items. Is it found?","a":"Yes. <code>i moved house last week</code> also finds the delivery-address question, but with a low score of 0.33.","h":"tpbfxh"}],"l2607":[{"t":"Read the config","q":"What are GPT-2's layer count, width and context length?","a":"12 layers, 12 heads, width 768 and a context of 1,024 tokens, with 124,439,808 parameters. It has no padding token.","h":"66oyt6"},{"t":"Loss of any text","q":"The same words, scrambled. What happens to the loss?","a":"It rises from 3.43 to 7.81, and perplexity from 31.0 to 2,466.2. The model finds ordinary English far less surprising.","h":"12rjgy0"},{"t":"The logit lens","q":"If you read the model's guess after each block, when does <code> Paris</code> appear?","a":"Only near the top: <code> France</code> and <code> Paris</code> show after block 11. Early blocks guess common words such as <code> not</code> and <code> now</code>.","h":"1bnc7ja","o":[1,13]},{"t":"Padding and masks","q":"Two prompts of different length go into one batch. What marks the padding?","a":"The attention mask: 0 for the padding position and 1 for real tokens. Padding goes on the left so that generation continues from the real text.","h":"1pr02x0"}],"l2701":[{"t":"Quality filters","q":"A cleaning filter looks at five documents. Which does it drop?","a":"The keyword spam, the menu and the short one: too repetitive, too many symbols, too short or with no sentence ending. Simple rules remove a lot of web text before training.","h":"1w8xrdi"},{"t":"Deduplication","q":"Texts a and b are exact duplicates. How similar is a to c, and a to d?","a":"0.50 and 0.00. A fingerprint finds exact copies. A similarity score also finds near-copies.","h":"2ap0q0"},{"t":"Scaling laws","q":"Compute grows ten thousand times. How far does the loss fall?","a":"From 2.308 to 1.915. The best model size grows from 2.8B to 309.0B parameters, with roughly 20 tokens of data per parameter throughout.","h":"13y27ab"}],"l2702":[{"t":"Chat templates","q":"What does the chat template add around the two messages?","a":"Special tokens: each message is wrapped in <code>&lt;|im_start|&gt;</code> and <code>&lt;|im_end|&gt;</code> with its role. The template turns a list of messages into the one string the model reads.","h":"12exndw"},{"t":"Preferences","q":"The chosen answer has reward -1.0 and the rejected one +1.0. Is the loss high or low?","a":"High: 2.13, because the model prefers the wrong answer. When it already prefers the chosen one by a wide margin, the loss is 0.05.","h":"wn41gi"}],"l2703":[{"t":"Thinking is computation","q":"An 8B model answers in 5 tokens, or thinks for 4,000. How much more computation is the second?","a":"800 times: 6.4e+13 against 8.0e+10 FLOPs. Each token is one more pass through the network.","h":"1nw3owd"},{"t":"Voting","q":"Voting over 45 samples: does it help when the model repeats the same mistake?","a":"No. Accuracy stays near 40% (36.7% at 45 samples). When wrong answers are scattered, voting lifts it to 99.4%.","h":"1es29am"},{"t":"Verifying","q":"A single try succeeds 10% of the time, and you can check answers. What is the chance that one of 20 tries is right?","a":"88%. With a checker, weak attempts add up. This works only when you can verify an answer.","h":"1i8pcov"}],"l2704":[{"t":"Fluent and wrong","q":"GPT-2 completes <code>The capital of France is the city of</code>. What is its top guess?","a":"<code> Marse</code>, the start of Marseille, at 0.129, ahead of <code> Paris</code> at 0.111. The text is fluent and the fact is wrong.","h":"118le7q"},{"t":"Plausible is not true","q":"Does the model always find the true statement less surprising than the false one?","a":"No. It prefers the false statement about Mount Everest and about Australia's capital. The model scores how plausible text is, not whether it is true.","h":"11w4yk0"},{"t":"Injected instructions","q":"The document contains the line <code>ignore all previous instructions</code>. Does the prompt mark it as different from yours?","a":"No. Your system text and the document are both just text in one prompt, and both contain lines that look like instructions.","h":"d4e292"}],"l2705":[{"t":"Cost per month","q":"Two models at different prices handle the same traffic. What does each cost per month?","a":"$2,250 on the large model and $188 on the small one. A price per request looks tiny until it is multiplied by volume.","h":"1k6qmgs"},{"t":"Self-hosting","q":"A GPU costs $4 an hour. What does a million output tokens cost when it is busy 5% of the time?","a":"$8.89, against $0.59 at 75%. Self-hosting is cheap only when the GPU is kept busy.","h":"ofye19"},{"t":"Will it fit?","q":"Does an 8B model fit on a 16 GB laptop?","a":"In 4-bit, yes (6.4 GB). In bf16 it needs 18.0 GB and a 24 GB GPU. Quantisation decides what fits.","h":"x72aot"}],"l2706":[{"t":"Images as tokens","q":"An 8 × 8 image is cut into patches. How many tokens does the transformer receive?","a":"4 tokens, each a vector of 64 numbers. Each patch of 16 pixels becomes one token, like a word.","h":"11mqyyn"},{"t":"Pictures and captions","q":"Three images and three captions. Where are the high similarities?","a":"On the diagonal: 0.99 for each matching pair. Contrastive training pulls matching pictures and captions together and pushes the rest apart.","h":"1oa6utf"},{"t":"Audio","q":"One second of sound is 16,000 numbers. What does the spectrogram show?","a":"Which frequency is strong in each short frame: 440 Hz at the start and 880 Hz at the end. The grid is 40 frames by 201 frequencies.","h":"xsbp7s"}],"l2707":[{"t":"Measuring fairness","q":"Both groups are about equally qualified. Are qualified people invited at the same rate?","a":"No: 90% in group A and 72% in group B. One overall number would hide this, so break results down by group.","h":"13uyeiy"},{"t":"Redaction","q":"What does <code>redact</code> leave of the email address, the phone number and the card number?","a":"Placeholders: <code>[EMAIL]</code>, <code>[PHONE]</code> and <code>[CARD]</code>. The order number stays, because the task needs it.","h":"172w71x"}],"l0101":[{"t":"Caching the prefix","q":"The prompt prefix is cached. How much does that save per turn?","a":"About half: $0.0612 against $0.1260, or $6,120 against $12,600 for 100,000 turns a month. Every call re-reads the history, so caching and short histories are the first cost levers.","h":"umgarw"},{"t":"Tokens per language","q":"The tokenizer was trained on English. How many tokens does the Hindi sentence take?","a":"19, against 4 for each English sentence. Text the tokenizer never saw falls apart into small pieces, and you pay per token.","h":"xv6jv0"}],"l0102":[{"t":"Where the time goes","q":"A long prompt with a short answer takes 9.05 s. What does caching the prefix do?","a":"It brings the total down to 1.8 s, with the first token after 0.55 s. A short prompt with a long answer still takes 19.18 s: output tokens are the expensive part of latency.","h":"1pbujpz"}],"l0103":[{"t":"Temperature","q":"At temperature 0.2, how likely is <code>shipped</code>, compared with temperature 1.0?","a":"0.82 against 0.50. A low temperature sharpens the choice, which is why extraction and classification use low temperatures. At 1.0 the ten samples mix <code>shipped</code> and <code>delivered</code>.","h":"us1ts0"},{"t":"A scoring matrix","q":"The cheapest model has the best score, 0.90. Is it chosen?","a":"No. It is below the quality floor, so the choice is frontier-mid. Apply the floor first, then compare cost and speed.","h":"q7mkq8"}],"l0104":[{"t":"Mask and cache","q":"The attention weights have zeros above the diagonal. Why?","a":"That is the causal mask: a token cannot look at later tokens. The last line is the KV cache at work: the cached result equals a full recomputation.","h":"12fsybd"},{"t":"RoPE","q":"With RoPE, the same two vectors sit at positions 5 and 2, then at 1005 and 1002. Do the scores differ?","a":"No: -8.4462 each time. Attention sees the distance between tokens, not their absolute positions. At distance 1 the score changes.","h":"1cmiam5"},{"t":"Mixture of experts","q":"A mixture-of-experts model stores 46.7B parameters. How many run for each token?","a":"About 12.9B, because each token goes to 2 of the 8 experts. The catch is that every expert must still sit in memory.","h":"96q57q"}],"l0201":[{"t":"One response","q":"What comes back from one API call besides the text?","a":"A stop reason (<code>end_turn</code>), a list of content blocks, and the usage: 70 input tokens and 15 output tokens.","h":"oij6ev"},{"t":"A growing list","q":"By the third question, how many messages does the helper keep?","a":"Six, and the token total has reached 384. The whole history goes with every call, which is why long conversations get trimmed or summarised.","h":"9aoigb"}],"l0202":[{"t":"Prose is not data","q":"You ask politely for JSON and call <code>json.loads</code> on the reply. What happens?","a":"It fails. The reply starts with <code>Sure! Here's the ticket as JSON:</code> and wraps the JSON in a code fence. Code cannot read prose.","h":"1joujlf"},{"t":"A schema from a class","q":"With a schema, what does the SDK hand back?","a":"A <code>Ticket</code> object with typed fields: <code>category='delivery', urgency=5, order_id='SK-1002'</code>. The SDK wrote the schema from your class.","h":"ic56eu"},{"t":"Before and after","q":"The same four tickets, asked nicely and then with JSON outputs. How many parse?","a":"0 of 4 when asked nicely and 4 of 4 with JSON outputs.","h":"2b682h"}],"l0203":[{"t":"Streaming text","q":"With streaming, when do the first words arrive?","a":"After 0.1 s, and the last after 0.7 s. The reply arrives in pieces as it is written, so the customer is not left staring at nothing.","h":"1higpdl"},{"t":"Server-sent events","q":"What does a stream consist of on the wire?","a":"A sequence of events: <code>message_start</code>, a block start, text deltas such as <code>'Let me '</code>, and finally <code>message_stop</code>.","h":"ca0exl"}],"l0204":[{"t":"No caching","q":"Three questions with the same 1,300-token system prompt and no caching. How much is read from the cache?","a":"Nothing. About 1,300 tokens are paid in full each time.","h":"2p4cxi"},{"t":"A cache breakpoint","q":"With a breakpoint on the system prompt, what changes on the second request?","a":"1,288 tokens are read from the cache and only 11 are uncached. The first request writes the cache and the next ones read it.","h":"ko1gma"},{"t":"The real SDK","q":"Through the real SDK, does the pattern hold?","a":"Yes: <code>written 1288</code> on the first request and <code>read 1288</code> on the second.","h":"875pk0"}],"l0205":[{"t":"One shape","q":"Two providers behind one adapter. What does the caller get from each?","a":"The same <code>Reply</code> shape with the same text. The adapter hides each provider's own call and response format.","h":"9kaxbh"},{"t":"A cut-off reply","q":"The reply is cut off at 10 tokens. Does your code see that the same way for both providers?","a":"Yes: <code>finished=False</code> for both. Each provider reports a cut-off in its own way, and the adapter reads both.","h":"7475vo"}],"l0206":[{"t":"Zero-shot and few-shot","q":"Twelve tickets, first with instructions only and then with four examples. How many replies are valid labels?","a":"4 of 12 zero-shot and 12 of 12 with examples. Examples fix the format at once. Correctness improves less: 5 of 12.","h":"1yv5jld"},{"t":"A prompt search","q":"Twelve candidate prompts are scored on a development set. Does the winner also do better on tickets the search never saw?","a":"Yes: 9 of 12 on the test set, against 5 for the hand-written prompt. The winning instruction is the plainest one, a one-line question.","h":"obepvf","tail":3},{"t":"Choosing the examples","q":"The examples are picked by keyword similarity. Is every pick a good one?","a":"No. The second pick matched the word <code>change</code> to an address example. Keyword similarity is shallow.","h":"23q0e0"}],"l0207":[{"t":"Self-consistency","q":"Each reasoning path is right 40% of the time. Does voting over 15 paths help?","a":"No. It drops to 21%, because the wrong answer wins the majority more often. At 75% per path, 15 votes reach 98%.","h":"ndkjwv"}],"l0208":[{"t":"A context budget","q":"The context budget is tight. How many history turns are kept?","a":"Four, in 350 words. The assembler fills the budget by priority. Real systems count tokens and summarise the turns they drop.","h":"1jgg4pq"},{"t":"Marking untrusted text","q":"How is the customer review wrapped before it goes into the prompt?","a":"In a tag with a random name, with a rule saying the text inside is data to analyse. This lowers the success of injected instructions but does not eliminate them.","h":"rl5h2g"},{"t":"Compaction","q":"At a budget of 300 tokens, what happens to the 19 messages?","a":"They collapse to 6, with the old turns replaced by one summary. At 600, clearing old tool results is enough, and at 2,000 nothing changes.","h":"u95fki"}],"l0209":[{"t":"Versions and hashes","q":"Version 2 of the prompt uses a variable that is not supplied. What happens?","a":"It is caught: <code>'tier' is undefined</code>. Each version has a hash, so a trace can prove which wording ran.","h":"45sc38"},{"t":"Static checks","q":"Does version 2 pass the static checks?","a":"No: it is missing required sections such as <code>&lt;role&gt;</code> and <code>&lt;instructions&gt;</code>. Static checks catch broken prompts. Whether the agent behaves is a job for the eval set.","h":"expikw"}],"l0300":[{"t":"The loop","q":"How many steps does the agent take for the refund question?","a":"Three: it asks for <code>find_order</code>, then for <code>calculator</code>, then answers. The model chose each step after seeing the last result.","h":"ekdzaz"},{"t":"The same as a workflow","q":"The same task as a fixed workflow. Does it reach the same answer?","a":"Yes, Rs 2249, with no model deciding the steps. When the steps are known in advance, a workflow is simpler and more predictable.","h":"3d6kfh"}],"l0301":[{"t":"Function and description","q":"Does the model ever run <code>get_order_status</code>?","a":"No. Your code runs it. The model sees only the description, and it sees the output only if your code sends it back.","h":"1puogc5"},{"t":"A wrong argument","q":"The customer writes the ID as <code>sk1042</code>. What happens?","a":"The first call fails validation, the error goes back as a <code>tool_result</code> with <code>is_error: true</code>, and the model corrects the ID. All six questions pass.","h":"pbij81"},{"t":"The SDK's runner","q":"The SDK's tool runner handles the same question. How many requests does it make?","a":"Three: a failed call, a corrected call and the answer, the same as your version.","h":"2r6nd6"}],"l0302":[{"t":"A loop with no limits","q":"The model keeps asking for the same tool. What does an agent with no limits do?","a":"It makes 40 requests and spends about 57,000 tokens to tell the customer nothing. The guarded agent stops at the third identical call, after 937 tokens.","h":"t9cqqa"},{"t":"The gate","q":"The agent now has a gate on <code>issue_refund</code>. Is any money refunded?","a":"No: <code>money refunded: {}</code>. The loop stops at the risky tool and says it needs a colleague's approval.","h":"1wk6f4m"}],"l0303":[{"t":"Two descriptions drift","q":"A teammate renames the function's parameter and nobody updates the hand-written schema. What happens?","a":"A <code>TypeError</code>: the model still sends <code>order_id</code>, and the function no longer accepts it. Two descriptions of one function drift apart.","h":"1vcnzec"},{"t":"Validation","q":"The model sends <code>reason: \"broken\"</code>. What does validation reply?","a":"That <code>reason</code> must be one of the allowed values. The message names the argument and says how to fix it, which lets the model correct itself on the next request.","h":"d298az"},{"t":"Smaller tool results","q":"The tool returns only the fields needed instead of the full API record. Do the answers change?","a":"No, and each run uses about a third fewer tokens.","h":"1piy5gj"}],"l0304":[{"t":"A failing tool","q":"The carrier API fails for the second customer. What do they see?","a":"<code>Sorry, I couldn't check that</code>, with a transient error. One failing tool call becomes the customer's answer.","h":"1butyp3"},{"t":"Parallel calls and a retry","q":"Two lookups run in parallel and one fails once. How many calls reach the carrier for SK-1077?","a":"Two: one failed and one retried. The customer gets both answers.","h":"118epkw"},{"t":"Idempotency","q":"A refund is retried after a lost reply. How many refunds are made without an idempotency key?","a":"Two, <code>R-901</code> and <code>R-902</code>. With a key the retry returns the first refund, so there is one.","h":"863312"}],"l0305":[{"t":"A run only in memory","q":"The process crashes mid-run and the run starts again. How often does <code>find_orders</code> execute?","a":"Twice. Nothing was saved, so the second run repeats the work: 5 model requests in all.","h":"1da0byo"},{"t":"An approval that waits","q":"The refund needs approval. What state is the run left in, and has money moved?","a":"<code>waiting_for_approval</code>, with the pending tool call stored as data, and no money moved. The run waits as data, not as a blocked thread.","h":"1gr8s6q"}],"l0306":[{"t":"Events","q":"What does the customer see while the agent works?","a":"Progress lines: <code>Looking up your orders</code>, <code>Checking the delivery status</code>, and then the answer. The loop yields events as it goes.","h":"1w7ynfm"},{"t":"Cost per run","q":"A three-step question costs about USD 0.004. What is that at 10,000 conversations a day?","a":"About USD 1,225 a month. More steps mean more input tokens, because each step re-reads the history.","h":"18jcx0z"},{"t":"Events to a browser","q":"The agent's events are sent to a web page as they happen. Does the browser see the tool's raw input?","a":"No. The server sends a friendly label such as <code>Looking up your orders</code>, then the answer. Raw tool inputs and results stay on the server.","h":"8zrrlk"}],"l0307":[{"t":"A chain with a gate","q":"The chain has a gate. What happens to the reply that promises a delivery date?","a":"It is held for review: <code>fail: promises a date</code>. A gate between steps stops a bad draft before it goes out.","h":"iyqzph"},{"t":"Routing","q":"Where does the router send <code>where is my parcel</code>?","a":"To the delivery flow. A misroute sends the user down the wrong path however good each path is, so measure the router on its own.","h":"2lpl2w"},{"t":"Evaluator and optimizer","q":"The evaluator rejects round 1. What happens next?","a":"The writer gets the feedback and round 2 passes. Always bound this loop, and decide what happens if it does not converge.","h":"ly734l"}],"l0308":[{"t":"ReAct","q":"ReAct answers one question. How many model calls does it take?","a":"Eight, and the model reads 5,232 characters in total, because every call re-reads the whole history.","h":"abt3bl"},{"t":"A plan meets a surprise","q":"The plan runs, and one lookup comes back not found. What does the solver do?","a":"It answers with what it has and says that it could not find SK-49001. A solver that assumes every step succeeded would fail here.","h":"1wy2x3v","tail":1},{"t":"Search","q":"With a beam width of 1 the search is greedy. Does it find the cheapest price?","a":"No: Rs 1,820. A width of 2 finds Rs 1,580 by keeping a second option alive. A width of 6 costs more evaluations and finds nothing better.","h":"rd9c7y"}],"l0309":[{"t":"A token budget","q":"The conversation outgrows its token budget. What survives?","a":"A summary, <code>gold Hindi A-1001</code>, plus the last 4 turns word for word, in 47 tokens. The first three turns were folded into the summary, and the facts survived.","h":"xoehfc"}],"l0310":[{"t":"Scopes","q":"Customer 77 prefers Tamil. Customer 42 asks which language to use. What does the store return?","a":"Only customer 42's own memory, the Hindi preference. The scope filter runs before similarity, so another customer's memory is invisible.","h":"nnqngb"},{"t":"Consolidation","q":"A later conversation says the customer now wants refunds on card. Does the store add a second fact?","a":"No. It updates the fact in place and keeps the old value in its history. The duplicate Hindi preference is skipped.","h":"1rxoy4c"},{"t":"Learning from feedback","q":"After feedback, what goes into the next prompt for a similar case?","a":"A learned rule about gold customers with damaged items, and a past case with its rating. The agent improves without retraining, so review learned rules like any prompt change.","h":"161l0em","o":[1,9]}],"l0311":[{"t":"Supervisor","q":"A supervisor asks two specialist agents. How many model calls does one answer take?","a":"Six, against two for a single agent with both tools. Specialists cost extra calls, so add them only when they earn it.","h":"12gg0kz"},{"t":"Handoff","q":"The customer is handed from triage to refunds. Do they have to repeat themselves?","a":"No. The refunds agent receives the full history, including why the customer was transferred.","h":"ica5oo"},{"t":"Fan-out with a budget","q":"Six subtasks fan out with a token budget of 6,000. What happens to the last two?","a":"They are refused: <code>budget exceeded</code>. Four finish. With a budget of 12,000 all six run, in two waves of three.","h":"1mzojpp"}],"l0312":[{"t":"Engineer the loop","q":"The loop runs the tests after each attempt. How many iterations until it stops?","a":"Four. The failing test names go back to the model as feedback, a repeated attempt is rejected, and the loop stops when all tests pass.","h":"doox67"},{"t":"State in files","q":"Session 3 cannot make feature F3 pass. What does it leave for the next session?","a":"A note in the progress file: <code>F3 blocked: tests fail, see notes</code>. State that lives in files outlasts any one session.","h":"6gq0eu","o":[1,7]},{"t":"Ratchet every failure","q":"The same failure happens twice. How many rules are added to the agents file?","a":"One. A duplicate failure does not add a duplicate rule. When a rule keeps being broken, promote it from text to code.","h":"1kc6wpk"}],"l0313":[{"t":"A coding agent","q":"The coding agent starts with a failing test. Can it edit the test to make it pass?","a":"No. The test file is protected: the agent may read it but not write it. The tests are the definition of done.","h":"xqv3t0"},{"t":"A browser agent","q":"The browser agent reads the page as a list of elements. What is in element 4?","a":"Customer reviews, and one of them is addressed to AI agents and tells them to ignore their instructions. Page content is untrusted input.","h":"1lxhcxm"},{"t":"A research agent","q":"The research report cites its sources. Were all of them read?","a":"No. <code>S9</code> matches no source that was read. Check every citation against the sources that were retrieved.","h":"1ldopwk"}],"l0401":[{"t":"Three ways it fails","q":"Three more questions go through the thirty-line RAG. Is the answer about express delivery right?","a":"No. It says express delivery is free above INR 499, mixing two sentences of the shipping page: express costs INR 99. Retrieval found the right page and the answer is still wrong.","h":"fghqxw","o":[1,11]}],"l0402":[{"t":"Extracting text","q":"A digital PDF is read with <code>extract_text</code>. What happens to the table?","a":"The text is exact, but the table becomes lines of words and its structure is gone.","h":"q38hav"},{"t":"Rebuilding the table","q":"After rebuilding the table, how can code check that it was read correctly?","a":"With arithmetic: each row's quantity times its rate equals its amount, and the rows add up to the subtotal.","h":"g5esb2","o":[1,6]},{"t":"Two columns","q":"The page has two columns. In what order does the file store the text?","a":"Line by line across both columns, so <code>Refund policy</code> and <code>Shipping</code> are mixed. Using the positions of the words, left column first, restores the reading order.","h":"136xij8","o":[1,7]}],"l0403":[{"t":"Chunks","q":"Six help pages are split into chunks. How many chunks are there?","a":"Nine, each with an id such as <code>refund-policy#1</code> and the name of its document.","h":"gu7gat"},{"t":"Match small, return big","q":"Search matches a sentence. What can be returned in place of the sentence?","a":"Its parent chunk or the whole document. Match at the sentence level, where meaning is sharp, and return enough context to answer.","h":"1gb5a5u"},{"t":"Propositions","q":"Nine chunks are rewritten as propositions. How many are there?","a":"29. Each proposition carries its subject, so a fact can be found without the rest of its chunk.","h":"rfq6p3"}],"l0404":[{"t":"Rare words","q":"<code>the</code> appears in six of nine chunks and <code>cod</code> in one. Which gets the higher weight?","a":"<code>cod</code>, at 1.90 against 0.43. Rare words carry more information.","h":"1j60556","o":[1,7]},{"t":"Repetition","q":"A word appears ten times in a chunk. Does it earn ten times the credit?","a":"No, 2.17 times. Fifty mentions earn 2.43. A chunk cannot win by repeating a word.","h":"180a9un"},{"t":"Words, not meaning","q":"<code>pay when it arrives</code> means cash on delivery. Does keyword search find the COD chunk?","a":"No. It returns a shipping chunk first, because no word matches. Keyword search finds words, not meaning.","h":"1qfcccq"}],"l0405":[{"t":"An embedding model","q":"Four sentences go through an embedding model. What comes back?","a":"A table of 4 rows and 384 columns, each row of length 1. No single number means anything on its own. The meaning is in the direction of the whole vector.","h":"onom49"},{"t":"Vector search","q":"<code>pay when it arrives</code>: does vector search find the COD chunk?","a":"Yes, <code>cod#0</code>, where keyword search returned a shipping chunk. <code>stop my purchase</code> now finds the cancellation chunk too.","h":"1n4cbyl"},{"t":"Where vectors fail","q":"Two error codes differ by one digit. Can the embedding model tell them apart?","a":"Barely: the right entry and a different one tie at 0.61. Keyword search separates them, and for a code that does not exist it correctly returns nothing.","h":"9tarqk","o":[1,6]}],"l0406":[{"t":"Two searches disagree","q":"Keyword search and vector search answer the same three questions. Do they agree?","a":"On the first and third they put the same chunk first and disagree below it. On <code>pay when it arrives</code> they disagree completely.","h":"54fjb7","o":[1,9]},{"t":"Scores do not add","q":"Can you add a BM25 score to a cosine score?","a":"No. BM25 reaches 1.61 here and might reach 12 for another query, while cosine stays between about 0 and 1. Adding them lets one method drown out the other.","h":"fiolyu"},{"t":"A reranker","q":"Hybrid search has the right chunk, <code>cod#0</code>, in third place. What does the reranker do?","a":"It moves <code>cod#0</code> to first. A reranker reads the question and each passage together, which neither search does.","h":"s6y0my","o":[1,8]}],"l0407":[{"t":"Measure first","q":"Eight test questions and three search methods. Which scores best?","a":"Hybrid: recall@3 of 1.00 and MRR of 0.79. Eight questions prove nothing statistically. The habit of measuring is the point.","h":"cs0j03"},{"t":"Four metrics","q":"The top three results hold two relevant chunks, and there are two in all. What are precision@3 and recall@3?","a":"0.67 and 1.00. MRR is 1.00 because the first result is relevant.","h":"bbrdg9"},{"t":"Checking citations","q":"The answer cites its sources. What does the citation check verify?","a":"That every cited passage was among those retrieved, and that nothing in the answer was left uncited.","h":"mka8xv"}],"l0408":[{"t":"The leak","q":"A customer asks about fraud refunds. What does unfiltered search return?","a":"The finance team's document, which a customer must not see. Filtering after the search leaves nothing, and filtering before it returns the documents this user may read.","h":"1jiy6sk","o":[1,8]},{"t":"A test for CI","q":"Across three users and four questions, how often does unfiltered search return a forbidden passage?","a":"44 times. Keep this test in CI: whoever asks, nothing may come back that they are not allowed to read.","h":"a6tnwe"},{"t":"Freshness","q":"On Tuesday one page changes and an offer ends. What does the sync do?","a":"It re-embeds only the changed page and deletes the offer, so the old offer can no longer be found.","h":"1ip0t1s"}],"l0409":[{"t":"IVF","q":"IVF with one probe compares about 1% of the vectors. What recall does it reach?","a":"0.665: it misses a third of the true neighbours. Eight probes reach 1.000 with about 1,400 comparisons.","h":"15nv29b"},{"t":"HNSW","q":"HNSW at efSearch 64: how many comparisons per query does 0.999 recall take?","a":"About 447, roughly 2% of the collection. The work grows slowly with efSearch.","h":"1u2nfdy"},{"t":"The filtering trap","q":"A filter keeps 1% of the data. What recall does post-filtering the global top 10 give?","a":"0.01, almost nothing. An exact scan of the 203 matching vectors gives 1.00 with 203 comparisons.","h":"1iokesi"}],"l0410":[{"t":"Context headers","q":"A one-line context header is added to each chunk. What happens to keyword MRR?","a":"It rises from 0.64 to 0.78.","h":"100ixbt"},{"t":"HyDE","q":"The plain question ranks a shipping chunk first. What does HyDE change?","a":"It searches with a hypothetical answer written in the corpus's own words, and <code>cod#0</code> comes first.","h":"qe3l2i"},{"t":"MMR","q":"The FAQ page and the policy chunk are 89% similar. What does MMR do?","a":"It keeps one of them and gives the other slots to different content. Ranking by relevance alone spent two of three slots on the same thing.","h":"1yp4ed"}],"l0411":[{"t":"Corrective retrieval","q":"<code>Do you sell car insurance?</code> is rewritten and searched again. What is returned?","a":"Nothing: the system abstains with <code>no relevant sources</code>. The first question, about speedy shipping, was rewritten into the corpus's words and succeeded.","h":"ajzp10"},{"t":"Two hops","q":"The question needs two facts. How many retrievals are made?","a":"Two. The first finds the cancellation rule, and the second uses it to fetch the UPI refund timing.","h":"b129xy"},{"t":"Follow-up questions","q":"<code>Is there a fee for that?</code> is searched as asked. What does it find?","a":"The cash-on-delivery chunk, the only one with the word <code>fee</code>. Condensing the follow-up with the earlier question gives a query that stands on its own.","h":"t9tfxi","o":[1,6]}],"l0412":[{"t":"The eval set","q":"The eval set has 27 questions. Are they all of one kind?","a":"No: 9 direct, 7 with typos, 8 real, 1 Hinglish and 2 unanswerable. Synthetic questions alone are too easy, because they reuse the passage's words.","h":"e9a4jo"},{"t":"Confidence intervals","q":"BM25 scores a recall@3 of 0.88. How sure is that number?","a":"Not very: its 95% interval runs from 0.76 to 1.0. Hybrid reaches 1.0 in every segment.","h":"1jwrnkc"},{"t":"Abstention","q":"Both unanswerable questions are caught. At what cost?","a":"One false abstention in 25 answerable questions: <code>What does faster delivery cost?</code>","h":"hnfv9q"}],"l0413":[{"t":"A document tree","q":"With no vectors, how is the passage found?","a":"By walking the document's tree of headings: Seller Policy Manual, then Fees and payouts, then Payout cycle.","h":"1udsohv"},{"t":"Read it all, or retrieve","q":"A corpus of 400,000 tokens and 10,000 questions a month. What does reading the whole corpus each time cost, compared with RAG?","a":"2,109 against 135. Even with cached input at a tenth of the price, reading everything on every question costs more than retrieving the relevant part.","h":"1qbp009"}],"l0414":[{"t":"A tracer","q":"The tracer follows a question through each stage. What does it report when the answer is nowhere to be found?","a":"<code>NOT IN THE INDEX</code>: check parsing, chunking and ingestion before anything else.","h":"1su7uig","tail":3}],"l0415":[{"t":"Hard negatives","q":"Random negatives or hard negatives: which leaves more to learn?","a":"Hard negatives: the loss is 1.636, against 0.000 with random ones. A loss near zero means there is nothing left to learn from.","h":"1k662nh"},{"t":"Fine-tuning","q":"Four epochs of fine-tuning. What happens to recall@1 on new wordings?","a":"It rises from 6% to 100%, as the loss falls from 2.832 to 0.188.","h":"1j9tzwq"}],"l0416":[{"t":"A semantic layer","q":"The question asks for <code>sales by location</code>. What does the semantic layer supply?","a":"The definition of revenue: the sum of amounts for delivered orders only. Without it, a model would sum every order.","h":"1nv9ik3"},{"t":"Validating SQL","q":"Four SQL statements are validated. Which are refused?","a":"A <code>DROP</code>, two statements in one, and a query on <code>sqlite_master</code>. Only a single <code>SELECT</code> on allowed tables passes.","h":"6hyzs6"},{"t":"A cost pre-check","q":"A query joins two tables with no date filter. What does the cost pre-check say?","a":"<code>full scan of ord without a date filter</code>. The message goes back to the writer like any other error.","h":"1kxz8kn"}],"l0417":[{"t":"Share of the answer","q":"OurCo's page gains a specific, quotable claim. What happens to its share of the answer?","a":"It rises from 0.18 to 0.54.","h":"1as7y9w"},{"t":"What gets cited","q":"The original page shares few words with the question. How often is it cited?","a":"Never. The edited page is cited twice and gets a share of 0.62.","h":"180gfkq"},{"t":"Measure many times","q":"150 answers per engine: how wide is the confidence interval?","a":"About 15 points, for example 31% to 46%. One run per prompt can be further off than that, so measure many times.","h":"yixc8r"}],"l0501":[{"t":"Paths","q":"The graph is queried for paths from customers to suppliers. What does one result look like?","a":"A path: <code>Priya -&gt; o1 -&gt; Phone X -&gt; Acme Electronics</code>. The same graph can be written as 12 triples.","h":"1qe0a2l"},{"t":"Several hops","q":"Only Priya buys a product supplied directly from China. Who is exposed to a Chinese supplier?","a":"All three customers, because Acme Electronics sources a component from Shenzhen Parts. Following several hops finds what a single lookup misses.","h":"9o37e3"}],"l0502":[{"t":"Create the graph","q":"After the <code>CREATE</code> statement, how many nodes and relationships does the graph hold?","a":"Twelve of each. Unlike the dictionaries of Lesson 5.1, this graph lives in a database that knows its schema.","h":"1xfkq04"},{"t":"A pattern","q":"The pattern has three nodes and two relationships. What does it return?","a":"Each customer with each product they bought: four rows. The middle node, <code>(:Purchase)</code>, has no name because nothing is returned from it.","h":"1a7qm7x"},{"t":"Following suppliers","q":"The query follows suppliers as well. Which row is supplied directly from China?","a":"Only the phone case, from Shenzhen Parts. The other rows appear because Acme Electronics sources a component from Shenzhen Parts.","h":"16mbfii"}],"l0503":[{"t":"Loading twice","q":"The same four tables are loaded three times. How many nodes are there afterwards?","a":"Still 11 nodes and 9 edges, because each row maps to one node by its key. Two customers share the name Priya Sharma and stay separate, because the key is the ID.","h":"4wz2pe"},{"t":"Provenance","q":"How does the graph know that the phone case comes from Shenzhen Parts?","a":"The edge records its source: the <code>products.supplier_id</code> column. Provenance on every edge lets you check any answer.","h":"1s649de"}],"l0504":[{"t":"Extraction","q":"Seven facts are extracted from four documents. Is the company always spelled the same?","a":"No: <code>Acme Electronics</code>, <code>Acme</code> and <code>ACME Electronics</code>. Each fact also records the document it came from.","h":"1it90ke"},{"t":"Validate and resolve","q":"Two of the extracted facts are invented. What happens to them?","a":"They are rejected: one uses a relation the schema does not have, and in the other a battery makes a company. The three spellings of Acme are merged into one node.","h":"1wcimfy","o":[1,9]},{"t":"Quality","q":"Precision is 1.00 and recall is 0.88. What was missed?","a":"<code>Earbuds Pro, MADE_IN, India</code>, because the schema has no <code>MADE_IN</code> relation. That is a gap in the schema, not an extraction error.","h":"pldjb9"}],"l0505":[{"t":"Traversal","q":"Postgres goes down. How far does the outage reach?","a":"Both agents in two hops, and on to the router and the gateway. A traversal gives the list of things to alert, degrade or route around.","h":"1gg61vc"},{"t":"PageRank","q":"PageRank is personalised from Meera. What does it rank highest?","a":"Her phone, its maker and related items. The from-scratch PageRank matches networkx.","h":"7rl76q","o":[1,6]}],"l0506":[{"t":"Joining facts","q":"The question needs three facts from two documents. What does the graph answer?","a":"MixPro Mixer is a top seller, it is supplied by Kaveri Appliances, and Kaveri had cracked jars in batch 7. Each fact comes with a citation.","h":"fk81na"},{"t":"A global question","q":"A question about the whole corpus: how many supplier clusters carry quality risk?","a":"2 of 3. Each community is summarised once at indexing time, and the summaries answer questions about the whole corpus.","h":"1u1di63"},{"t":"Three retrievers","q":"Three retrievers on multi-hop questions. Which finds all the evidence?","a":"Graph expansion: evidence recall of 1.00, against 0.67 for keyword search. It reads more chunks per question to get there, 5.2 against 3.0.","h":"valhrw"}],"l0507":[{"t":"Traversal explosion","q":"One hop reaches a median of 5 nodes. What can three hops reach?","a":"A median of 964 nodes, and in the worst case 10,444, half the graph. Skipping the highest-degree nodes halves that.","h":"1jfzxq7"},{"t":"Security","q":"A support agent in another tenant asks for Priya's neighbours. What do they see?","a":"Only that tenant's own data, a different purchase. Within a tenant, the role decides which edges are visible.","h":"10qotqx"}],"l0508":[{"t":"An agent on a graph","q":"A battery is recalled. How much of the graph does the agent read to find the maker to notify?","a":"Five of nine edges, in five tool calls. It follows only the relations that serve the question and reaches Acme Electronics.","h":"146u2qu","o":[1,6]},{"t":"Memory with time","q":"Priya moved in June 2026. Where did she live when the March 2026 order shipped?","a":"Pune. The new city closes the old fact instead of overwriting it, so the memory answers both <code>today</code> and <code>in March</code> correctly.","h":"qm302n"}],"l0601":[{"t":"The scripted model","q":"The scripted model is asked about two orders. What does it return?","a":"Two parallel tool calls, as a real model would. The rules are crude on purpose: the point is to exercise each framework's plumbing.","h":"zk8mmd"}],"l0602":[{"t":"An AIMessage","q":"What does a chat model return besides the text?","a":"An <code>AIMessage</code> with a finish reason and usage: 50 input tokens and 20 output tokens.","h":"10x6ppv"},{"t":"Stream","q":"The reply is streamed in 19 chunks. What does adding the chunks together give?","a":"One <code>AIMessageChunk</code> with the whole text and the usage. Chunks add up.","h":"1ccvdat"},{"t":"Batch","q":"Three questions are sent with <code>batch</code>. What is the total token usage?","a":"150 input and 60 output tokens, collected by the usage callback across all three calls.","h":"1j3lr6p"}],"l0603":[{"t":"A prompt template","q":"The prompt template is invoked with a tier, a history and a question. What comes out?","a":"A list of messages: the system message with <code>gold</code> filled in, the history, and then the question. The template also reports its input variables.","h":"10gym40"},{"t":"The pipe","q":"<code>prompt | chat | parser</code>: what type does each step produce?","a":"<code>ChatPromptValue</code>, then <code>AIMessage</code>, then <code>str</code>. Running the steps by hand gives the same result as the chain.","h":"m32ifq"},{"t":"assign","q":"<code>RunnablePassthrough.assign(reply=chain)</code>: what keys does the result have?","a":"The original keys plus <code>reply</code>. <code>assign</code> adds a key and passes everything else through.","h":"1ckur8c"}],"l0604":[{"t":"A function becomes a tool","q":"A decorated function becomes a tool. What will the model get to see?","a":"A name, a description taken from the docstring, and the argument schema: <code>order_id</code>, a string.","h":"1ljgr3y"},{"t":"Tool calls","q":"The model is asked about two orders. What comes back?","a":"Empty content, a finish reason of <code>tool_calls</code>, and two tool calls with their arguments and ids. Nothing has run yet.","h":"vvotlg"},{"t":"Typed output","q":"<code>with_structured_output(Triage)</code>: what does the call return?","a":"A <code>Triage</code> object: <code>category='refund', urgent=False</code>. With <code>include_raw=True</code> you also get the raw message and any parsing error.","h":"jgpp31"}],"l0605":[{"t":"An agent in one call","q":"One call to the agent answers a question about two orders. What is in the final state?","a":"The whole list of messages: the question, the model's tool calls, the tool results and the answer.","h":"l7m4z0","o":[1,6]},{"t":"The loop is a graph","q":"Streaming the agent shows its steps. Which nodes run?","a":"<code>model</code>, then <code>tools</code>, then <code>model</code> again. The agent loop is a graph with two nodes.","h":"1jzljv7"},{"t":"A checkpointer","q":"With a checkpointer and one thread ID, how many messages are in the thread after the second question?","a":"Eight, four from each turn. The checkpointer keeps the conversation, so <code>And A-1002?</code> is understood.","h":"jbxeg5"}],"l0606":[{"t":"Where middleware runs","q":"Middleware hooks run around the model call. In what order?","a":"<code>before_model</code>, then <code>wrap_model_call</code>, then <code>after_model</code>, on every turn of the loop.","h":"5su97t","o":[1,8]},{"t":"A limit","q":"The model call limit is 1. How does the run end?","a":"With a message: <code>Model call limits exceeded: run limit (1/1)</code>. The run ends gracefully and raises no exception.","h":"essc3b"},{"t":"Summaries","q":"With summarisation switched on, what is the first message after the second question?","a":"A summary of the conversation so far. The thread stays at 4 messages while the conversation keeps growing.","h":"7al46n"}],"l0607":[{"t":"Split, keep metadata","q":"The pages are split into 14 chunks. What does each chunk keep?","a":"Its metadata: the source file, the topic and the start index.","h":"1c0omzn"},{"t":"A filtered search","q":"The search is filtered to one source. What comes back?","a":"Only chunks from <code>shipping.md</code>. Without the filter the refund policy is first, with a score of 0.97.","h":"102yfv7"}],"l0608":[{"t":"The built-in fake","q":"The built-in fake chat model is given to <code>create_agent</code>. What happens?","a":"<code>NotImplementedError</code>: it cannot bind tools. The lesson builds a scripted model that can.","h":"vtultm"},{"t":"A scripted model","q":"A scripted model drives the agent. What can the test assert?","a":"The exact sequence of messages, and what the tool was called with: <code>['A-1001']</code>. The test needs no network and costs nothing.","h":"1bxk89o"},{"t":"Callbacks","q":"A callback records the run. What events does it see?","a":"A model call with 1 message in, the tool call and its result, and a second model call with 3 messages in.","h":"o6dxq0"}],"l0609":[{"t":"Lint, pause, resume","q":"The graph has an unreachable node. When is it found?","a":"Before anything runs: the linter reports <code>orphan is unreachable</code>. The run then pauses for approval and resumes from its checkpoint.","h":"164zu2l"}],"l0610":[{"t":"Draw the graph","q":"The graph is drawn from its own edges. In what order do the nodes run?","a":"<code>classify</code>, <code>lookup</code>, <code>decide</code>, between <code>__start__</code> and <code>__end__</code>.","h":"5dowvv"},{"t":"The messages reducer","q":"<code>add_messages</code> receives a <code>RemoveMessage</code> for id 2. What is left?","a":"Messages 1 and 3. The messages reducer appends new messages and removes the ones you name by id.","h":"mjwydv"}],"l0611":[{"t":"Conditional edges","q":"Two messages enter the graph. Where does the question about gift cards go?","a":"To a person. A conditional edge chooses the next node from the state.","h":"1c9gqlm"},{"t":"Per-run context","q":"The same graph runs for a gold and a silver customer. What differs?","a":"Gold is refunded automatically and silver needs approval, with a limit of INR 5,000. The tier comes from per-run context.","h":"hqhtd5"}],"l0612":[{"t":"Threads","q":"Two chats use one function. Does chat-2 see chat-1's history?","a":"No. Each thread ID has its own saved history.","h":"1w1ac27"},{"t":"History of a thread","q":"The thread's history is listed. What does each checkpoint record?","a":"The step, the node that runs next and the state keys so far, newest first.","h":"4walig"},{"t":"Time travel","q":"The run is rewound to just before the refund and the amount is changed. What happens?","a":"The graph continues from there and refunds INR 4,999. The thread now holds 7 checkpoints: the old path is kept and a new branch is added.","h":"w3big1"}],"l0613":[{"t":"A node runs again","q":"The approval node pauses and is resumed. How many times does it start?","a":"Twice. On resume the node runs again from its first line, so code before the pause must be safe to repeat.","h":"1qb90u4"},{"t":"Resume with an answer","q":"The person declines the second refund with a note. What does the graph return?","a":"<code>declined: above the agent's limit</code>. <code>Command(resume=...)</code> hands the person's answer to the paused node.","h":"1kbd5vc"},{"t":"Validate the answer","q":"The person's answer fails validation. What happens?","a":"The graph asks again. A valid amount of 4,999 is then accepted and refunded.","h":"1ogixwx"}],"l0614":[{"t":"Thread and notebook","q":"A new thread starts on Tuesday. What does the bot still know about customer C-42?","a":"The notebook entry <code>Prefers replies in Hindi</code>. The thread history is new. The notebook is kept per customer.","h":"xfni1y"},{"t":"The store","q":"What does the store return for customer C-42's namespace?","a":"Both saved items: the language <code>Hindi</code> and <code>refund_to: UPI</code>. Memories are stored under a namespace and a key.","h":"iabaq0"},{"t":"Search by meaning","q":"<code>can you wrap it as a present?</code> Which memory is found?","a":"<code>Always asks for gift wrap</code>, with a score of 0.71, although the question shares no words with it.","h":"xl2j5q"}],"l0615":[{"t":"Stream modes","q":"Three stream modes run at once. What does each carry?","a":"<code>custom</code> carries your own status lines, <code>updates</code> what each node returned, and <code>messages</code> the model's tokens.","h":"1lhlh2i"},{"t":"The Functional API","q":"A workflow pauses for approval and is resumed. Are the earlier tasks run twice?","a":"No. <code>lookup</code> and <code>fraud_check</code> each appear once, because finished tasks are read back from the checkpoint.","h":"1oz01o2"}],"l0616":[{"t":"A graph as a node","q":"A compiled graph is used as a node. Whose steps does the stream show?","a":"Both: the parent's <code>triage</code>, then the subgraph's <code>find_order</code> and <code>refund</code> under the <code>refunds</code> namespace.","h":"cycvv4"},{"t":"Fan out with Send","q":"One message names three orders. How are they looked up?","a":"<code>Send</code> fans out one task per order, and the three results are gathered into one summary.","h":"9j3det"},{"t":"A supervisor","q":"The supervisor gets <code>Please cancel A-1002</code>. Which specialist handles it?","a":"<code>cancellations</code>. The status question went to <code>tracking</code>.","h":"15z30h1"}],"l0617":[{"t":"Over HTTP","q":"The graph runs behind a server and pauses for approval. What does the client get back?","a":"The question the graph is waiting on, and <code>next: ['approval']</code>. After the resume it returns <code>refunded INR 7,999</code>. A second run is streamed as updates, node by node.","h":"yy3a76"}],"l0618":[{"t":"A retry policy","q":"The payment call fails with a temporary error. What does the retry policy do?","a":"It runs the node again until it succeeds, and the refund is sent. Retry only the errors a retry can fix.","h":"1xlneqe"},{"t":"Timeouts","q":"A timeout is set on an ordinary, synchronous node. What happens?","a":"<code>ValueError</code>: node timeouts are only supported for async nodes. A synchronous call cannot be interrupted from outside.","h":"buayac"},{"t":"A saga","q":"A later step fails after the refund was already sent. What does the graph do?","a":"It undoes the earlier steps in reverse order: the refund is reversed and the slot released. The log shows <code>undo: refund sent</code>, then <code>undo: slot reserved</code>.","h":"wtf9oy"}],"l0624":[{"t":"Merge order","q":"A slow node and a fast node append to one list in parallel. Which item comes first?","a":"The same one every run: <code>['a', 'b']</code>, whichever finished first. Writes are applied in task-path order, not finish order.","h":"gztw8i"},{"t":"A write collision","q":"Two parallel nodes set a key with no reducer, on a graph with a checkpointer. What happens to the thread?","a":"<code>InvalidUpdateError</code>, and <code>get_state</code> fails too: the colliding writes were saved, so every read replays them until the key gets a reducer.","h":"1cipbp"},{"t":"A crash after paying","q":"A refund node pays, then the process dies before the node returns. What does the resume do, without a key and with one?","a":"Without a key it pays again: 2 ledger rows. With a key it finds the payment and skips it: 1 row.","h":"1oqz8xk"},{"t":"Checkpoint size","q":"A thread adds a 1 KB page per step for 100 steps. How big are its checkpoints, plain and with DeltaChannel?","a":"About 5,170 KB plain and about 160 KB with <code>DeltaChannel</code>, for about 100 KB of content.","h":"1scpppx"}],"l0625":[{"t":"Two requests, one thread","q":"Two workers get a request for the same thread at once. What do the clients get?","a":"One <code>200 ran</code> and one <code>409 busy</code>. A request afterwards runs normally.","h":"qfxza7"},{"t":"A store prefix","q":"Two users' memories are stored under ('users', id, 'memories'). What does a search on ('users',) return?","a":"Both users' memories. Searches match prefixes, so namespaces must be built from the authenticated user ID.","h":"13896qc"}],"l0619":[{"t":"A tool that writes state","q":"A tool sets the active customer. What can the next tool do?","a":"Read it from the state: it lists the open orders for C-42 without the model passing the ID. The customer ID never has to come from the model.","h":"1al40m9"},{"t":"Tools from MCP","q":"The agent connects to an MCP server. Where do its tools come from?","a":"From the server: it lists <code>get_order_status</code>, and the call returns <code>A-1001 is shipped</code> over MCP.","h":"1t3pvsu"},{"t":"A model per call","q":"Two questions reach the same agent. Which model answers each?","a":"The small model answers the order question and the large one handles the dispute. Middleware chooses the model per call.","h":"v2fwfa"}],"l0620":[{"t":"Files as memory","q":"The deep agent writes a report. Where does the file live?","a":"In the agent's state, under <code>files</code>. The agent can read it back later, so long work does not have to stay in the context.","h":"14mvzzv"},{"t":"A subagent","q":"The agent delegates log reading to a subagent. What comes back to the main agent?","a":"Only the finding: two timeouts from the payment service. The subagent's own reading stays out of the main context.","h":"1lgsbez"},{"t":"Permissions","q":"The agent tries to write to <code>/config/payments.yaml</code>. What happens?","a":"<code>permission denied</code>. It may write under <code>/reports</code> only, and the note there is saved.","h":"1ncqjy1"}],"l0621":[{"t":"Your own API","q":"The customer asks to cancel an order through your API. What does the endpoint return?","a":"<code>needs_approval</code>, with the action and its arguments. A second endpoint takes the decision, and then the order is cancelled.","h":"6azapk"},{"t":"Customers apart","q":"Another customer sends a decision for conversation 1. What do they get?","a":"A 409: nothing is waiting for a decision in their own conversation 1. An unknown token gets a 401.","h":"duvecw"},{"t":"Record and replay","q":"A recorded run is replayed in CI. Does the answer match?","a":"Yes. The model's replies come from the recording, and the tool itself runs again.","h":"obo6ju"}],"l0622":[{"t":"Build it","q":"The desk is compiled. Which nodes does it have?","a":"<code>redact</code>, <code>triage</code>, <code>tracking</code>, <code>refund</code> and <code>faq</code>. Every message is redacted, then routed to one of three specialists.","h":"gi7dhd"},{"t":"A day at the desk","q":"Six messages arrive, from two customers. How is the refund request handled?","a":"It pauses for approval, is resumed with <code>approved: True</code>, and the refund goes out. FAQ answers come back in the customer's language with a source.","h":"89agga","o":[1,7]},{"t":"Audit","q":"What was saved in the thread? Are there email addresses in it?","a":"None: redaction ran before anything was stored. The history also shows which route each message took.","h":"zej4dh"}],"l0623":[{"t":"Imports","q":"Do the imports this chapter used still work on the tested versions?","a":"Yes, and the library documents five error codes, starting with <code>GRAPH_RECURSION_LIMIT</code>.","h":"72ilxa"}],"l0701":[{"t":"An agent with tools","q":"The same question about two orders, in the OpenAI Agents SDK. What does <code>Runner.run</code> return?","a":"The final answer about both orders. The SDK ran the tool loop for you.","h":"1r9aalq"},{"t":"Approval","q":"The agent wants to cancel an order. What does the run do?","a":"It pauses for <code>cancel_order</code> and continues after approval. The paused state can be saved to a database, so an approval survives a restart.","h":"cxpnt9"},{"t":"A guardrail","q":"The customer pastes a card number. Does the message reach the agent?","a":"No. The input guardrail blocks it: <code>never paste card numbers into chat</code>.","h":"4aqeka"}],"l0702":[{"t":"A handoff","q":"The triage agent receives a refund request. Which agent ends up answering?","a":"<code>refunds</code>. A handoff transfers the conversation to another agent.","h":"p0uwfp"},{"t":"Run context","q":"The customer asks about an order that belongs to someone else. Where is that checked?","a":"In code, using the customer from the run context, so nothing in the prompt can talk the tool out of it.","h":"b1nldu"},{"t":"Tracing","q":"A lead agent calls a specialist as a tool. How do the spans nest?","a":"The specialist's tool call sits inside the specialist, which sits inside the lead's tool call. That nesting shows who called what.","h":"1mfa05t","o":[1,6]}],"l0703":[{"t":"An approval hook","q":"In Strands, the agent wants to cancel an order. What does the run return first?","a":"An interrupt, <code>cancel-approval</code>, with the order ID. After approval the order is cancelled.","h":"z1k31d"},{"t":"Steering","q":"A plugin forbids cancelling shipped orders. Does the cancel run?","a":"No. The tool call is cancelled and the model receives the reason, so it can offer a return.","h":"rxp5ul"},{"t":"Spans","q":"One request is traced. What spans does it produce?","a":"One <code>invoke_agent</code> span for the request, a cycle span per think-act round, a <code>chat</code> span per model call and an <code>execute_tool</code> span per tool.","h":"1lgvrkv","o":[1,6]}],"l0704":[{"t":"A confirmation","q":"In ADK, the agent wants to cancel an order. What does the tool do?","a":"It requests confirmation first. After it is confirmed, the order is cancelled.","h":"9cq9bz"},{"t":"State and scope","q":"A value is saved under <code>user:last_order</code>. Does a new session for the same user see it?","a":"Yes. A <code>user:</code> key follows the user across sessions, and a plain key such as <code>lookups</code> stays in its session.","h":"4htykc"},{"t":"Persisted events","q":"One question is asked with a database session service. How many events are stored?","a":"Four: the user message, the model's tool call, the tool result and the final answer. Another server can continue the conversation.","h":"c4wsd"}],"l0705":[{"t":"An approval","q":"In Microsoft Agent Framework, the tool has an approval mode. What does the run return?","a":"A request, <code>approval needed for cancel_order</code>, in place of running the tool. After approval the order is cancelled.","h":"1r6vk2k"},{"t":"A workflow that routes","q":"Two messages enter the workflow. Where does each go?","a":"The refund request goes to the refund desk and the parcel question to the general desk.","h":"7auhjr"}],"l0706":[{"t":"A crew","q":"A CrewAI crew is asked where an order is. What does it return?","a":"<code>A-1001 is shipped</code>. The crew is a set of agents with roles, working through tasks.","h":"7mpbl1"},{"t":"A flow","q":"The flow classifies a message and branches. What category does it record?","a":"<code>refund</code>, and it logs the request. A flow is event-driven code with state.","h":"1m1dapp"}],"l0707":[{"t":"Typed output","q":"In Pydantic AI, what type is <code>r.output</code>?","a":"A validated <code>Answer</code> object, not text. If the model returns something invalid, the library sends the error back and asks it to retry.","h":"1v9e1sm"},{"t":"A deferred tool","q":"The agent wants to cancel an order. What does the first run return?","a":"<code>DeferredToolRequests</code> for <code>cancel_order</code>. A second run with the decision completes the cancellation.","h":"1r4leo8"},{"t":"Dependencies","q":"The same question about the same order, from customers c-7 and c-9. Do they get the same answer?","a":"No. c-7 sees <code>shipped</code> and c-9 gets <code>not found for this customer</code>. The difference comes only from the dependencies your code passes in.","h":"6uamqj"}],"l0708":[{"t":"An index","q":"The index is asked about a refund for a damaged item. What does it return?","a":"The refund passage with a score of 0.87, and the document it came from. After that document changes, only it is re-indexed, and a new retriever returns the new text.","h":"1m2ej31"},{"t":"DSPy","q":"A DSPy signature declares <code>urgent</code> as a boolean. What comes back?","a":"<code>refund True</code>: a real boolean. DSPy parses outputs into the declared types.","h":"7egysq"}],"l0709":[{"t":"A tool-calling agent","q":"smolagents runs the same order question. What does it need from your tool?","a":"A docstring with an <code>Args:</code> section. Every run ends with a built-in <code>final_answer</code> tool.","h":"m4ujoc"},{"t":"An agent that writes code","q":"A code agent checks three orders. How many model calls does it need?","a":"One. It writes a short program that calls the tool three times and counts the result.","h":"utgyi2"},{"t":"The sandbox","q":"The code agent is asked to look at files and writes <code>import os</code>. What happens?","a":"The interpreter refuses the import, and the agent answers that it can only use the order tools.","h":"185x3wt"}],"l0801":[{"t":"A server in memory","q":"The server is tested in memory. What does <code>cancel_order</code> return for a shipped order?","a":"An error with a message: <code>A-1001 has shipped and cannot be cancelled</code>. The client receives the message, not the traceback.","h":"1669dar"},{"t":"Raw messages","q":"A method that does not exist is called. How does the server answer?","a":"With a JSON-RPC <code>error</code>, code -32601. An unknown tool is different: it is a normal <code>result</code> with a message in words.","h":"1gxokab"}],"l0802":[{"t":"HTTP with auth","q":"The server is called over HTTP with no token. What happens?","a":"The call fails with an <code>MCPError</code>. With a token, a bad order ID comes back as a tool error that says what IDs look like.","h":"m2zo6"},{"t":"An agent with MCP","q":"An agent is connected to the server. Where is the tool defined in the agent's code?","a":"Nowhere. The agent discovered <code>get_order_status</code> from the server at run time.","h":"9ync7i"},{"t":"Elicitation","q":"A tool needs the user to confirm. What does the host show?","a":"The server's question: <code>Really cancel A-1002? This cannot be undone.</code> On yes the order is cancelled, and on decline it is left unchanged.","h":"yojc3q"}],"l0803":[{"t":"Description drift","q":"A tool's description changes after it was approved. What do the checks report?","a":"<code>CHANGED</code> for that tool, and the scan finds the injected phrase <code>also call</code>. Block the server until a person reviews the new description.","h":"tcr8s2"},{"t":"A gateway","q":"The agent asks the gateway to delete a customer. What happens?","a":"It is refused, <code>not available to this agent</code>, and the attempt is written to the audit log as <code>denied</code>.","h":"h4ia9t"}],"l0804":[{"t":"A2A tasks","q":"A remote agent is asked for a refund with no order ID. What state does the task end in?","a":"<code>INPUT_REQUIRED</code>, asking which order. The caller answers with another message on the same task. The first request ran through to an artifact with the decision.","h":"j0rjou","o":[1,7]},{"t":"AG-UI events","q":"What does an agent send to a front end during one run?","a":"A stream of typed events: the run starts, a tool call starts and its arguments arrive, and at the end the run finishes.","h":"1rbd0st"}],"l0901":[{"t":"Validate the extraction","q":"The extracted total is changed by 100. What does validation do?","a":"It rejects it: <code>subtotal + GST is not the total</code>. Arithmetic and format checks are the cheapest and most reliable accuracy control in document AI.","h":"1l7s80n"},{"t":"Images across providers","q":"The same image is sent to four providers. Is the message format the same?","a":"No. Each has its own part names: <code>image_url</code>, <code>image</code>, <code>inline_data</code>. The idea is the same: text parts and image parts in one message.","h":"dpz6ws"},{"t":"Field-level accuracy","q":"A careless extractor gets 3 of 3 on three fields. Where does it fail?","a":"On the number of line items: 2 of 3. A document-level <code>it worked</code> would have hidden the missing line.","h":"oqdqkw"}],"l0902":[{"t":"What text extraction keeps","q":"Text is extracted from a bar chart. Does it contain the answer to <code>which month had the most refunds</code>?","a":"No. Every word of the chart is there and the information is gone, because the heights of the bars are not text.","h":"teuttz"},{"t":"Images and text together","q":"Images and questions are embedded in one space. Does <code>which month had the most refund requests</code> find the bar chart?","a":"Yes, <code>refunds_bar</code>, with no description of the image written by anyone. Each image became 512 numbers.","h":"iayski"}],"l0903":[{"t":"The latency budget","q":"A fully sequential voice pipeline takes 2,600 ms before the caller hears anything. What does streaming every stage give?","a":"1,120 ms, still above the target of about 800 ms. A turn-detection model and a faster model bring it to 820 ms, and a speech-to-speech model to about 530 ms.","h":"1ptek36"},{"t":"Speak in chunks","q":"The model's answer is still being written. When does speech start?","a":"At the first punctuation mark: <code>Your order A-1001 has shipped,</code> is spoken while the rest is generated. Chunking at punctuation keeps the intonation natural.","h":"85ps4u"},{"t":"End of turn","q":"The caller stops speaking at 1.1 seconds. When does a 900 ms silence rule decide the turn is over?","a":"At 2.00 s. Every rule adds its silence on top: 1.30 s with a 200 ms rule.","h":"o7d103"}],"l0904":[{"t":"A judge","q":"A classifier judges whether a picture looks like a real digit. How many real digits is it at least 90% sure about?","a":"77%. Even some real digits are sloppy, so 77% is the reference point for the generators that follow.","h":"1yvf9oz","tail":1},{"t":"A variational autoencoder","q":"Random points are decoded by the VAE. Do they look like digits of every class?","a":"Yes, across all ten classes. The tidy latent space is what lets random points decode to recognisable digits.","h":"lx4066","o":[1,12]},{"t":"Diffusion","q":"The denoiser's loss settles near 0.25 and stays there. Is training broken?","a":"No. Unlike a GAN's losses, this is a plain prediction error, and it cannot reach zero.","h":"17ff561"}],"l0905":[{"t":"Denoising","q":"Ten thousand samples of pure noise are denoised in small steps. Where do they end up?","a":"Half near -2 and half near +2, the two clusters of the training data. An image generator does the same thing with pixels in place of one number.","h":"1o00z8o"}],"l1001":[{"t":"A layered pipeline","q":"An output says <code>We guarantee a full refund</code> and cites a real passage. Does the output rail pass it?","a":"No: <code>makes a promise outside policy</code>. The input rail blocked an injection earlier, and personal data was replaced with placeholders.","h":"fxtsrk"},{"t":"Measure the rail","q":"The regex input rail has precision 1.00. What is its recall?","a":"0.62: it missed three attacks out of eight, including a paraphrase and one in another language. Measure a rail before you trust it.","h":"160rg3l"},{"t":"Fix or raise","q":"A validator finds a competitor mention. What are the two ways it can respond?","a":"Repair the output and pass it, or raise an error and block it. Log the original failure even when it is fixed.","h":"dbs1o2"}],"l1002":[{"t":"An injection works","q":"A product review contains hidden instructions. What does the summariser reply?","a":"<code>Refund approved for order A-1002.</code> It followed the review's text and wrote no summary.","h":"kcnmc4"},{"t":"Delimiters alone","q":"The review is wrapped in tags and the prompt says it is data, never instructions. Does that stop it?","a":"No. The reply is still <code>Refund approved for order A-1002.</code> Wording in the prompt is not a security boundary.","h":"wcrj58"},{"t":"A safer design","q":"The safer agent reads the same poisoned review. Is a refund issued?","a":"No. The summary is stored and flagged for review, and the refund decision is made by code that checks who is asking.","h":"1d9jizl"}],"l1003":[{"t":"A sandbox","q":"Untrusted code runs in a restricted process. What happens to an infinite loop?","a":"It is killed. Secrets from the environment are not visible and a memory bomb gets a <code>MemoryError</code>. This stops accidents and the cheapest attacks.","h":"cs8tx6"},{"t":"Red teaming","q":"The same attacks are run against the naive and the guarded agent. How many succeed against each?","a":"Each kind succeeds against the naive agent and none against the guarded one. The model still tries the calls, and the policy layer makes them harmless.","h":"1fkspos"}],"l1004":[{"t":"Risk tiering","q":"Two use cases are tiered by the same code. What does the support agent get?","a":"<code>medium</code>, with a list of required controls. Tiering is explicit, versioned and applied the same way to every project.","h":"164fqta","o":[1,17]},{"t":"Erasure","q":"Customer C-42 asks to be erased. Which stores still mention them afterwards?","a":"The traces and the semantic cache, because they are not keyed by customer ID. Tag every record with the subject's ID when you write it.","h":"12cwfj1","o":[1,6]}],"l1101":[{"t":"Compute-optimal training","q":"A compute budget of 5.88e+23 FLOPs: what model size and data does the rule suggest?","a":"About 70B parameters on 1.4T tokens. Llama 3 8B was trained far past that ratio, because a smaller model trained longer is cheaper to serve.","h":"11vw2c4"},{"t":"Perplexity","q":"A model gives the actual next tokens low probabilities. What is its perplexity?","a":"8.34, against 1.52 for the good model. Perplexity is roughly how many tokens the model is torn between at each step.","h":"1p2ool0"},{"t":"What SFT optimises","q":"In supervised fine-tuning, which tokens count toward the loss?","a":"Only the assistant's: <code>It ships today . &lt;end&gt;</code>. The prompt tokens are masked out.","h":"1m4tdhn"}],"l1102":[{"t":"A reward model","q":"A reward model is trained on 500 noisy comparisons. Does it recover what people value?","a":"Yes: the learned weights are close to the true ones, including the negative weight on length.","h":"1t6e92q"},{"t":"DPO","q":"The DPO loss starts at 0.693. What does it do as the chosen answer becomes more likely?","a":"It falls to 0.287. If training goes the wrong way and the rejected answer gains, it rises to 1.037.","h":"1felvwa"},{"t":"Group advantage","q":"Eight samples for one prompt are all correct. What advantage does each get?","a":"Zero: there is nothing to learn. A prompt the model always solves, or never solves, gives no signal.","h":"10aslkx"},{"t":"A policy gradient","q":"Four possible answers and a checker, with no correct answer ever shown. What happens to the probability of 43?","a":"It rises from 0.25 to 0.83 in ten steps and to 0.99 in fifty. With a careless checker that accepts any answer ending in 3, a third of the answers stay wrong.","h":"m2n53v","o":[1,10]}],"l1103":[{"t":"Why models bluff","q":"Under binary grading, when should a model guess?","a":"Always. Even at 20% confidence, a guess scores more than abstaining. Penalising wrong answers changes that.","h":"37d06v","o":[1,8]},{"t":"BLEU and ROUGE","q":"A correct paraphrase and an answer that says the opposite. Which scores higher on BLEU?","a":"The opposite one: 0.56 against 0.00. Word-overlap metrics cannot judge meaning.","h":"s8xmxh"},{"t":"Contamination","q":"58% of a benchmark question's 8-word windows appear in the training data. What does that mean?","a":"The question is contaminated: the model may have memorised it. Keep a private test set and refresh it.","h":"1fcfys0"}],"l1106":[{"t":"The dataset","q":"How large are the three sets?","a":"320 training, 40 validation and 40 test examples, each a ticket with its JSON label.","h":"19k6jmw","o":[1,10]},{"t":"The baseline","q":"With no training, how does the base model score on the test set?","a":"0.0 on valid JSON. It understands that JSON is wanted but invents its own keys or wraps the answer in prose.","h":"l8k2kf","tail":1}],"l1107":[{"t":"What the model reads","q":"What does one training example look like after the chat template?","a":"System, user and assistant messages wrapped in <code>&lt;|im_start|&gt;</code> and <code>&lt;|im_end|&gt;</code>, ending with the JSON answer.","h":"1bxte5c"},{"t":"A batch","q":"Of 558 real tokens in the batch, how many contribute to the loss?","a":"191, the answer tokens. The loss before training is 2.190, a probability of 11.2% per answer token.","h":"1z0dxeu"},{"t":"Did it work?","q":"After fine-tuning, how does the model do on phrasings it never saw?","a":"Valid JSON every time, but the intent is right only 42.5% of the time. On phrasings seen in training it scores 1.0.","h":"iustnp"}],"l1108":[{"t":"A small correction","q":"A LoRA wrapper is added to a layer. Does the output change at the start?","a":"No, because B starts as all zeros. The two thin matrices hold 9,216 numbers, 2.8% of the layer's 331,776.","h":"wzmbiv"},{"t":"Train it","q":"LoRA trains for 80 steps. What happens to the loss?","a":"It falls from 1.9544 to about 0.04 by step 40. The format is learned perfectly, and intent on unseen phrasings is still weak at 0.375.","h":"1db9drt","o":[1,9]},{"t":"With peft","q":"The <code>peft</code> library adapts all the weight matrices. How many weights are trainable?","a":"4,884,480, which is 3.5% of the total. Intent on the test set rises to 0.6.","h":"ti2tl9","o":[1,10]}],"l1109":[{"t":"Past the average","q":"The scores are broken down by true intent. Is every class equally good?","a":"No. <code>order_status</code> is 100% and <code>other</code> is 12%. Order numbers and urgency are right in every class.","h":"ptp0ym","o":[1,6]},{"t":"Read what it says","q":"When the model does not recognise a phrasing, what does it answer?","a":"Almost always <code>order_status</code>. That is why <code>order_status</code> scored 100%.","h":"qyn8b5"},{"t":"Is it asked the same way?","q":"The chat template is left out at inference. What does the model write?","a":"Unrelated text. The system message made no difference, but the template is essential.","h":"6n6uy7","o":[1,6]}],"l1110":[{"t":"Rounding by hand","q":"Five weights are stored in 4 bits. What happens to the three small ones?","a":"They all become 0.0. At 8 bits the values come back close to the originals, and at 2 bits everything is zero.","h":"6rdur3"},{"t":"The whole model","q":"The model is stored at 8 bits. What happens to its size and its score?","a":"It shrinks from 425 MB to 106 MB and scores the same 90%. At 3 bits, with this simple rounding, it scores 0%.","h":"lqr4hi","o":[1,6]},{"t":"Cost","q":"A large model with a few-shot prompt, or a small tuned model on a hosted service. What does each cost per month?","a":"$10,800 against $97, about a hundred times less.","h":"mq7qgk"}],"l1104":[{"t":"Traces to a dataset","q":"Five traces go through the filter. How many become training examples?","a":"Three: two for training and one for validation. A phone number in one of them is redacted first.","h":"1dmmbf3"},{"t":"Failed traces","q":"A failed trace becomes an eval case. Does the old answer pass it?","a":"No, and the fixed answer does. One training example is then removed, because the eval set asks the same question.","h":"chqxhw"}],"l1105":[{"t":"Distillation","q":"A small student is trained on a large teacher's labels. How often does it agree with the teacher?","a":"98.0% of the time, at about $10 a month against $3,000. Here it even beat its teacher, which you should not expect on real traffic.","h":"ci3hfa"},{"t":"Checking the data","q":"Three training rows are checked before upload. What is wrong with rows 1 and 2?","a":"Row 1 does not end with an assistant message and its turns do not alternate. Row 2 contains an email address.","h":"l48nxd"},{"t":"A grader","q":"A query is written differently from the reference and returns the same result. What score does the grader give?","a":"1.0, because the grader checks results, not text. A query that forgets the filter gets 0.2.","h":"10obptc"}],"l1111":[{"t":"Superposition","q":"Five features are stored in fewer dimensions. What does reading out feature 0 show?","a":"1.0 for feature 0, with small leaks of 0.2 into two others. The directions are about 72 degrees apart, not at right angles.","h":"1kmlbkb"},{"t":"A sparse autoencoder","q":"A sparse autoencoder is trained on the activations. How many distinct units do the five features use?","a":"Five, one unit per feature.","h":"hwqeid","o":[1,6]},{"t":"Steering","q":"Feature 3's direction is added to an activation. What does the read-out show?","a":"Feature 3 switches on at 1.4. Switching on the matching SAE unit does nearly the same.","h":"pzhw2h"},{"t":"A doubling trend","q":"A model can finish 12-hour tasks half the time, and that length doubles every 4 to 7 months. When does it reach a working week?","a":"In 7 to 12 months, if the trend holds. These are projections of a trend, so design limits that do not depend on the model being weak.","h":"hu219c"}],"l1201":[{"t":"A readiness review","q":"The refund agent passes its own evals. What does the readiness review decide?","a":"<code>NOT READY</code>, with 6 blocking findings, starting with a write tool that has no idempotency key and runs without approval.","h":"1d7cd5b","o":[1,12]},{"t":"After the fixes","q":"Version 0.4 passes. Was the prompt changed?","a":"No. Every fix is in the system around the model.","h":"j7iyw4"}],"l1202":[{"t":"Linting tool contracts","q":"A linter reads the tool contracts. What does it flag?","a":"Descriptions too short to say when to use the tool, a read tool with unbounded output, and a free-string customer ID.","h":"1hgij37","o":[1,16]},{"t":"FMEA","q":"Failure modes are ranked by risk priority number. Which is highest?","a":"<code>issue_refund</code> called twice after a timeout, at 48. Two failure modes at 40 or more must have a tested mitigation before launch.","h":"17qwrwr","o":[1,11]}],"l1203":[{"t":"Estimate first","q":"500,000 calls a day. What is the peak load?","a":"17.4 calls a second and about 6.5 million tokens a minute. The vector index needs 12.3 GB in float32 or 3.1 GB in int8.","h":"1wc66gp","o":[1,7]},{"t":"A latency budget","q":"Time to first token is 1,830 ms against a budget of 2,000 ms. Which change brings it down most cheaply?","a":"Routing with rules in place of a model call and caching the prompt prefix: 1,135 ms.","h":"112cp53"},{"t":"Availability","q":"A single provider is down about 323 minutes a month. What does failover to a second provider give?","a":"About 109 minutes, and a degraded mode when search is down brings it to 66.","h":"1q26s3b"}],"l1204":[{"t":"A small gateway","q":"The primary deployment is down. What does the gateway's log show?","a":"Each request tries the primary, then is served by the backup. A team over budget is blocked. Real gateways add a cooldown so that they stop trying a dead deployment.","h":"439e7g","o":[1,6]},{"t":"LiteLLM's router","q":"The first deployment fails. Who serves the request?","a":"The fallback deployment, and the caller sees a normal answer.","h":"4i6ky4"},{"t":"Virtual keys","q":"The intern team's key asks for the support model. What does the gateway return?","a":"A 403: that model is not allowed for the team. An unknown key gets a 401, and the provider sees the prompt with personal data already redacted.","h":"18h6scr","o":[1,6]}],"l1205":[{"t":"Size the memory","q":"An 8B model serves 32 users with 8k tokens of context each. What takes the most memory?","a":"The KV cache, more than half of about 50 GB. Long contexts and many users need memory far beyond the weights.","h":"1yqvnjw","o":[1,12]},{"t":"Continuous batching","q":"One 400-token request arrives with several short ones. What does continuous batching change?","a":"Mean latency falls from 266 steps to 78. Under static batching the short requests waited for the long one.","h":"d721yb"},{"t":"What users feel","q":"Concurrency goes from 4 to 16. What happens to time to first token?","a":"It jumps from about 0.2 s to 2.6 s while throughput stays at about 150 tokens a second. Only 4 of 16 requests meet the target.","h":"1qg2e5f"}],"l1206":[{"t":"Delegated tokens","q":"The agent asks for a scope its registered purpose does not include. Is it granted?","a":"No. The token carries only <code>orders:read</code> and <code>refunds:write</code>, names the user and the agent, and expires. A wrong audience or an expired token is denied.","h":"uolzsn"},{"t":"A policy decision point","q":"A refund over 5,000 INR is requested. What does the policy decide?","a":"<code>APPROVE</code>: it needs a person. Each decision names the rule that made it.","h":"1mu0bph","o":[1,6]},{"t":"A tamper-evident log","q":"One entry in the audit log is edited afterwards. Can that be detected?","a":"Yes: the chain is <code>broken at entry 1</code>. Each entry includes a hash of the one before it.","h":"7x15yt"}],"l1207":[{"t":"A retry storm","q":"The same failures hit a naive client and a hardened one. How many tasks does each complete?","a":"90.2% and 100.0%. The naive client loses about one task in ten, and a few of those stopped halfway with side effects already done.","h":"7yamj6"},{"t":"A saga","q":"The shipment service is down after the card was charged. How does run 1 end?","a":"With no money taken and no stock held: the charge is refunded and the stock released. A later run resumes without charging twice.","h":"1riwxog","o":[1,19]}],"l1208":[{"t":"Surviving a crash","q":"The process dies after calling the refund API and before sending the email. What happens after the restart?","a":"The refund API is not called again. Its result comes from the checkpoint, and only the remaining step runs.","h":"1ni6n4s","o":[1,6]},{"t":"A canary verdict","q":"The canary's judge fail rate is 9.5% against a baseline of 6.0%. What is the verdict?","a":"<code>ROLL BACK</code>. A canary at 6.3% is within noise and is promoted, and one with too little traffic has to wait.","h":"1fgehw0"}],"l1209":[{"t":"Backoff with jitter","q":"The provider returns 429 three times. How long does the client wait each time?","a":"Random waits below the growing limit, 0.32 s and 0.03 s here, so that a thousand workers do not all retry at the same instant. The third wait follows the server's Retry-After.","h":"1n9ynhk"},{"t":"Size it first","q":"Traffic doubles with a second region. What runs out first?","a":"The token quota, not the pods. Five pods handle the doubled traffic easily.","h":"3jdfm","o":[1,6]},{"t":"Fair scheduling","q":"A large batch arrives first in a single queue. How long do the small tenants wait?","a":"More than twenty minutes. With per-tenant queues they wait 38 s and 9 s, and the batch tenant waits longer.","h":"x0rtmh"}],"l1210":[{"t":"Cost per run","q":"A strong model with no caching costs $0.1710 per run. What does prompt caching do?","a":"It halves the cost, to $0.0835, without changing a word of the output. A cascade is cheap only if few requests escalate.","h":"1fmg6h5","o":[1,6]},{"t":"A router","q":"Routing between a small and a strong model: what does a threshold of 0.50 give?","a":"95.3% quality, within 1.4 points of always using the strong model, at about a third of the cost.","h":"1o6zum5","o":[1,6]},{"t":"Unit economics","q":"Which feature costs most per resolved outcome?","a":"Refunds, at $0.2070, about seventy times order status at $0.0028. A failed run still has to be paid for.","h":"lgiwps"}],"l1211":[{"t":"An eval harness","q":"Version 2 passes 6 of 6 where version 1 passed 3 of 6. How sure is the improvement?","a":"The pass rate rose by 0.50, with a 95% interval from +0.17 to +0.83. The judge agrees with the expert 90% of the time, a kappa of 0.76.","h":"e6axhl"},{"t":"Multi-turn evals","q":"Every single answer from the impatient agent looks helpful. What does the conversation show?","a":"It cancelled without confirmation, including a shipped order. Some behaviour exists only across turns.","h":"1stdh3g","o":[1,8]},{"t":"A gate in CI","q":"One eval fails. What does the CI job do?","a":"It exits with code 1, which fails the job. The failing case is the behaviour this release was meant to add, so the gate is doing its job.","h":"hdo78r"}],"l1212":[{"t":"pass^k","q":"Version 1 passes 93% of single trials. How often does it pass four in a row?","a":"76%. Version 2 reaches 98% and 93%. Reliability over repeated trials is what a customer feels.","h":"134jy9u"},{"t":"A release gate","q":"Version 2 is better on three tasks and worse on one. Is it released?","a":"No. It is blocked, because the one new failure is on a critical task: 9 of 10 where version 1 had 10 of 10.","h":"jh4fu"}],"l1213":[{"t":"OpenTelemetry","q":"One agent run is traced. How are the spans arranged?","a":"One root span for the run, a child per model call and tool call, and token counts on each model span, all in the same trace.","h":"nrau3u","o":[1,6]},{"t":"What to keep","q":"Of 10,000 traces, how many are kept?","a":"2,755, or 28%: every error, block, complaint and outlier, plus a 10% random sample of the ordinary runs.","h":"59gv7s"},{"t":"Burn rate","q":"The last hour used error budget much faster than the SLO allows. Is the on-call paged?","a":"Yes. Both the one-hour and the six-hour burn rates are over their limits.","h":"123bpt2","o":[1,7]}],"l1214":[{"t":"Triage","q":"300 runs are triaged. What do the detectors find?","a":"Eight runs that loop on the same tool call, and the same eight are over the step budget. A tool with an 11.3% error rate needs investigating.","h":"1b7e6pq","o":[1,8]},{"t":"Error signatures","q":"Two error signatures are counted by release. Which did release 0.5 introduce?","a":"The <code>search_kb</code> timeouts: all 29 are in 0.5. The orders-API errors are old noise spread across both releases.","h":"1w7cfdy"},{"t":"Replay","q":"A bad run is replayed against the fix. What changes?","a":"Release 0.5 claimed the refund was completed. The fix says it is in progress and what it cannot check, with no unverified claim of success.","h":"90jb07"}],"l1215":[{"t":"MLflow","q":"A prompt is registered and two calls are evaluated. What does MLflow record?","a":"Version 1 of the prompt, the scores of the two checks, and two traces with their spans.","h":"14vdwtx"},{"t":"A release manifest","q":"Two parts of the release changed. What follows from that?","a":"A new fingerprint, and the list of evals to run for exactly those parts: groundedness, retrieval recall and the support suite.","h":"twnnlk"},{"t":"Gates follow the change","q":"A release changes the prompt, the model and the tools. Which gate is added for the new tool?","a":"An approval, because a new write tool widens what the agent can do.","h":"1qbr5w0","o":[1,8]}],"l1216":[{"t":"Approval routing","q":"2,000 actions in a day are routed by risk. How many need a review?","a":"369. One reviewer approves 99.3% in a median of 3 seconds, which is a rubber-stamping risk.","h":"npjbbo"},{"t":"A handoff packet","q":"The agent escalates to a person. What does the packet carry?","a":"The customer, the goal, what was done and the evidence, with no required field missing. The colleague can decide in one step.","h":"rrmxa5","o":[1,8]}],"l1217":[{"t":"Handoffs as contracts","q":"One agent hands another a churn figure as a string with no source. What does the contract do?","a":"It rejects it: the value should be a float and the source is missing. A stale figure is rejected too.","h":"dx1wjd"},{"t":"A registry","q":"An agent has no owner on call, no evals and no budget. What does the registry do?","a":"<code>BLOCK DEPLOY</code>. Another agent has tools outside its purpose and must fix that before its next release.","h":"628vv5"}],"l1219":[{"t":"A design review","q":"A design is checked against the review rules. What is the high-severity finding?","a":"Untrusted inputs with no egress controls. The design is strong on the basics and has this one real gap.","h":"5ywnha"}],"l1301":[{"t":"Converse","q":"The Converse API handles a question that needs a tool. How many model calls are made?","a":"Two: one stops with <code>tool_use</code> and the next with <code>end_turn</code>. It is the loop from Lesson 3.2 with different message shapes.","h":"14pv9j8"},{"t":"A runtime app","q":"What does an AgentCore Runtime app have to answer?","a":"A health ping and an <code>/invocations</code> request, which returns the answer and the session.","h":"17ix682"}],"l1302":[{"t":"A SageMaker endpoint","q":"An agent calls a fraud model as a tool. What comes back?","a":"A score, 0.07. A classic model behind an endpoint is a good agent tool.","h":"1e1pmas"},{"t":"Invocation logs","q":"The invocation logs are queried. What do they show for the support agent?","a":"4,120 calls and 1,840,233 input tokens. The logs contain full prompts, so encrypt them and restrict access.","h":"sgzmxs"},{"t":"The policy simulator","q":"A least-privilege policy is tested before use. Which calls are denied?","a":"Invoking an unapproved model and deleting a knowledge base. Only the approved inference profile is allowed.","h":"kb43z7"}],"l1303":[{"t":"A Foundry agent","q":"One question goes to a Foundry agent. How many HTTP calls does it take?","a":"Four: create the agent version, open a conversation, then two turns of the tool loop. Agent versions are immutable.","h":"1lakuw1"},{"t":"A knowledge base","q":"The knowledge base answers a question. What else does it return?","a":"Its own activity trace: the planning step and the index search, with the time each took, and the references it used.","h":"waciuc"},{"t":"Prompt Shields","q":"The user's request is harmless, but the document carries an injection. What does Prompt Shields report?","a":"No user attack, and a document attack. That is the indirect-injection case from Lesson 10.2.","h":"1vut3wx"}],"l1304":[{"t":"PII redaction","q":"A message with a phone number and an email goes to the language service. What comes back?","a":"The redacted text and the categories found. Run it before logging or storing transcripts.","h":"hdzqke"},{"t":"Document Intelligence","q":"An invoice is analysed. Which field should go to a person?","a":"The invoice date, with a confidence of 0.62. The other fields are at 0.95 or more.","h":"1ks2p2n"}],"l1305":[{"t":"Gemini with tools","q":"A question that needs a tool goes to Gemini on Agent Platform. Where did the request run?","a":"On a regional endpoint in Mumbai, <code>asia-south1</code>. The first call asks for the tool and the second answers.","h":"n82ll0"},{"t":"Memory Bank","q":"A later session asks what is remembered about the customer. What is returned?","a":"<code>Customer prefers refunds to UPI.</code> Memory Bank generated that fact from an earlier conversation.","h":"1xgac83"}],"l1306":[{"t":"De-identification","q":"A message is sent to Sensitive Data Protection. What comes back?","a":"The text with <code>[PHONE_NUMBER]</code> and <code>[EMAIL_ADDRESS]</code> in place of the values.","h":"t6iwwf"},{"t":"Vector search in SQL","q":"A policy search runs inside BigQuery. How does the user's question reach the SQL?","a":"As a query parameter, never pasted into the SQL string. The closest policy has the lowest distance, 0.18.","h":"bdz0wh"}],"l1307":[{"t":"A ResponsesAgent","q":"One request to the agent is traced by MLflow. Which spans appear?","a":"<code>predict</code>, a model call, the tool <code>get_order_status</code>, and a second model call.","h":"3thz55"},{"t":"Evaluate","q":"The agent is evaluated before deployment. What do the two scorers report?","a":"1.0 for mentioning the status and 1.0 for using the order tool.","h":"b7yyd4"}],"l1308":[{"t":"A Cortex Agent","q":"A question about late deliveries goes to a Cortex Agent. What does the stream show?","a":"A planning status, the analyst tool being called, the generated SQL, and then the answer. Showing the SQL makes the answer checkable.","h":"5belxu"}],"l1401":[{"t":"Retrieval","q":"<code>My blender arrived broken, can I get my money back?</code> shares few words with the policy. What is retrieved?","a":"The passage on damaged or defective items.","h":"29j48r"},{"t":"Tools enforce the rules","q":"The customer asks to refund an order that belongs to someone else. What does the tool reply?","a":"<code>not found on your account</code>. It says <code>not found</code> and not <code>forbidden</code>, so the answer reveals nothing about other accounts.","h":"1gnzit3"},{"t":"The release gate","q":"The release gate runs. What must hold for a release?","a":"Regression at 90% or more over three trials, safety at 100%, and cost under the limit. Here all three pass.","h":"nisjaa"}],"l1501":[{"t":"The cache decides the bill","q":"The same agent and the same tokens, with three ways of building the prompt. How far apart are the costs?","a":"Sixfold: USD 3.19 per run with a broken cache and USD 0.54 when the context is append-only.","h":"v58uud"},{"t":"Score your design","q":"Your design made 3 of 5 load-bearing decisions. What should you read?","a":"The misses and their reasons. A score is not the point.","h":"wjnlbe","o":[1,8]}],"l0001":[{"t":"Who it is for","q":"What background do you need before you start this course?","a":"None in AI, Python or maths. The course teaches each one when you first need it."},{"t":"Marks in the text","q":"A term has a dotted underline, or a small <code>later</code> pill after it. What does that tell you?","a":"The term is taught in another lesson. You get a one-line meaning now and a link to where it is taught."},{"t":"Study habits","q":"Name the three habits that make a lesson stick.","a":"Predict before you run, recall without rereading, and change the code."},{"t":"The stack","q":"How many layers does every agentic system have, whatever the vendor?","a":"Six, plus concerns that cut across all of them. The course teaches the layers in turn."}],"l0002":[{"t":"The project","q":"Why does the course keep all its code in one project folder with a virtual environment?","a":"So that the course's packages stay separate from everything else on your computer. You add packages to the same project when a chapter asks for them."},{"t":"API keys","q":"How should you treat an API key?","a":"Like a password: it is a secret billed to your account. Keep it in a <code>.env</code> file that never goes into git. Most of the course runs without one."},{"t":"Stand-ins","q":"Do you need a paid model to run the examples?","a":"No. Most examples run offline against stand-ins, and each lesson says which kind it uses."}],"l0004":[{"t":"Rules and expert systems","q":"Why did the first two eras of AI run out of road?","a":"They wrote rules by hand. Expert systems stored thousands of if-then rules and worked only in narrow domains."},{"t":"Deep learning","q":"What changed with deep learning?","a":"Networks learned their own features from raw data, and kept improving with more data and computing power."},{"t":"Three ingredients","q":"Why did the big jumps happen when they did?","a":"Because data, compute and methods improved at the same time."},{"t":"A lesson from history","q":"What does history teach someone building with AI today?","a":"Hype runs ahead of reality, and sounding right is not being right."}],"l0105":[{"t":"Reading a model","q":"A new model is announced. How do you place it?","a":"Read its name, and ask the lesson's four questions about it."},{"t":"The cutoff","q":"A model's knowledge stops at its training cutoff. Where must anything current come from?","a":"From tools or retrieval."}],"l0710":[{"t":"Where it fits","q":"What kind of agent is the Claude Agent SDK suited to?","a":"Agents that work on files, code, shells and long tasks. It is the Claude Code harness as a library."},{"t":"Using it safely","q":"The SDK's power is its built-in tools. What is most of the work of using it safely?","a":"Deciding what it may do: permissions, hooks and which tools it is allowed."}],"l0711":[{"t":"How to choose","q":"Several frameworks could do the job. How do you choose?","a":"Answer the lesson's questions in order. The first strong constraint usually decides."},{"t":"No-code tools","q":"A business team wants to build an agent in a low-code tool. When is that the right place?","a":"For a prototype. Anything customer-facing belongs in code you can test."},{"t":"The landscape","q":"Why learn what the older tools were?","a":"Because the tools in Chapters 6 and 7 make more sense when you know what they replaced."}],"l1218":[{"t":"Support at scale","q":"A support assistant handles 50,000 conversations a day. Does every conversation go to an agent?","a":"No. Fixed paths take most of the traffic and the agent handles the rest. Writes are idempotent and gated."},{"t":"Many tenants","q":"Where are permissions enforced in a multi-tenant knowledge assistant?","a":"Inside retrieval, and every cache and index is keyed by tenant."},{"t":"Text-to-SQL","q":"For a text-to-SQL agent, which cost should you watch?","a":"The warehouse cost per query, not tokens. Build a semantic layer per business domain."},{"t":"Defending a design","q":"Is there one correct design?","a":"No. Several designs can be sound. What matters is the reasoning and the trade-offs you state."}],"l1309":[{"t":"Twelve jobs","q":"The platforms have very different product lists. What do they have in common?","a":"Every agent platform does the same twelve jobs. Learn the jobs once, then look up each platform's names."},{"t":"Choosing","q":"Do most organisations pick a single platform?","a":"No. They end up with a primary cloud, a data platform and a few SaaS agents."}],"l1402":[{"t":"Rank the use cases","q":"Five candidates are scored on value, feasibility and harm. Which comes first, and which comes last?","a":"Order-status answers first, by a factor of twelve: high volume, a checkable answer and little harm. Contract review is last, because few contracts arrive and nobody can cheaply check a review.","h":"1nnaixb"},{"t":"A range, not a number","q":"The same system at 30% and at 75% automation. Does it pay back?","a":"At 30% it loses money and never pays back. At 75% the build is paid for in 7.9 months. At 60%, moving from 1% to 6% wrong resolutions turns the profit into a loss.","h":"1ihiixd","o":[1,11]},{"t":"Build or buy","q":"A product charges per resolution. At 72,000 resolutions a month, is buying or building cheaper over three years?","a":"Building on a platform: INR 25.3 million against 29.5 million. At 20,000 resolutions a month, buying is cheaper. Volume decides.","h":"lf1rol"}]};

/* Zero to Agents · the Replay part of a lesson: a few of the lesson's own recorded runs, shown again as "predict, then reveal",
   plus the "carry forward" list on the last part. Data: window.ZXR (replays.js, written by replays/build_rp.py). */
window.ZXRP = (function () {
  let el, ic, $, $$, esc, Z;
  const NOT = /^(def |class |import |from |@|#|[\)\]\}]|"""|'''|async def |else|elif|except|finally)/;
  function hash(s) { s = s.replace(/[ \t\n\r]+/g, " ").replace(/^ | $/g, ""); let h = 5381; for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0; return h.toString(36); }
  function blocks(code) {
    const L = code.replace(/\n+$/, "").split("\n"), out = [];
    for (let i = 0; i < L.length; i++) {
      const l = L[i]; if (!l.trim() || /^\s/.test(l) || NOT.test(l)) continue;
      let j = i; while (j + 1 < L.length && (!L[j + 1].trim() || /^\s/.test(L[j + 1]) || /^([\)\]\}]|else|elif|except|finally)/.test(L[j + 1]))) j++;
      while (j > i && !L[j].trim()) j--;
      out.push(L.slice(i, j + 1)); i = j;
    }
    return out;
  }
  function excerpt(code, c) {
    const B = blocks(code); let pick;
    if (c) { const needles = Array.isArray(c) ? c : [c]; pick = needles.map(n => B.find(b => b.join("\n").indexOf(n) >= 0)).filter(Boolean); if (pick.length !== needles.length) pick = null; }
    else { const all = code.replace(/\n+$/, "").split("\n"); if (all.length <= 12) return all.join("\n"); pick = B.slice(-3); }
    if (!pick || !pick.length) return c ? null : code.replace(/\n+$/, "").split("\n").slice(0, 8).join("\n");
    return pick.map(b => b.length > 12 ? b.slice(0, 11).concat(["    …"]).join("\n") : b.join("\n")).join("\n");
  }
  function hl(text, lang) { try { if (window.hljs && lang && window.hljs.getLanguage(lang)) return window.hljs.highlight(text, { language: lang, ignoreIllegals: true }).value; } catch (e) {} return esc(text); }
  function has(lid) { return !!(window.ZXR && window.ZXR[lid] && window.ZXR[lid].length); }
  function build(L, wrap, h) {
    Z = h; el = h.el; ic = h.ic; $ = h.$; $$ = h.$$; esc = h.esc;
    carry(L, wrap);
    const sec = $('.zx-stage[data-kind="replay"]', wrap); if (!sec || !has(L.id)) return;
    const body = $(".zx-stage-body", sec), S = window.ZXR[L.id], labs = {};
    $$(".zx-lab", wrap).forEach(lab => { const pre = $(".code pre", lab), out = $(".zx-out pre", lab); if (pre && out && !lab.closest(".zx-excard")) { const k = hash(pre.textContent); if (!labs[k]) labs[k] = lab; } });
    const steps = S.map(s => {
      if (!s.h) return { t: s.t, q: s.q, a: s.a, plain: true };
      const lab = labs[s.h]; if (!lab) { problems.push(L.id + " run not found: " + s.t); return null; }
      const cls = ($(".code code", lab) || {}).className || "", lang = (/language-(\w+)/.exec(cls) || [])[1] || "python";
      const code = excerpt($(".code pre", lab).textContent, s.c); if (code == null) { problems.push(L.id + " code not found: " + s.t + " / " + JSON.stringify(s.c)); return null; }
      const all = $(".zx-out pre", lab).textContent.replace(/\n+$/, "").split("\n"), a = s.tail ? Math.max(1, all.length - s.tail + 1) : s.o ? s.o[0] : 1, b = s.tail ? all.length : Math.min(all.length, s.o ? s.o[1] : all.length <= 8 ? 8 : 4);
      if (a > all.length) { problems.push(L.id + " output range: " + s.t); return null; }
      const stage = lab.closest(".zx-stage");
      return { t: s.t, q: s.q, a: s.a, code: code, lang: lang, out: all.slice(a - 1, b).join("\n"), full: all.join("\n"), more: all.length - (b - a + 1), pre: a > 1, from: stage ? ($(".zx-stage-title", stage) || {}).textContent : "", si: stage ? +stage.dataset.i : -1, tailOpen: !s.tail && b < all.length };
    }).filter(Boolean);
    if (!steps.length) { sec.classList.add("zx-empty"); return; }
    const runs = steps.some(s => !s.plain), box = el("div", "zx-replay zx-ui"); let i = 0; const seen = new Set();
    box.innerHTML = '<p class="zx-rp-intro">' + (runs ? "These are runs you saw in this lesson. For each one, say what you expect before you reveal what really happened. Being wrong and then seeing why is the fastest way to learn." : "Answer each question in your own words, then reveal the answer and compare.") + "</p>" +
      '<div class="zx-rp-top"><ol class="zx-seq-steps">' + steps.map((s, k) => '<li><button type="button"><b>' + (k + 1) + "</b>" + esc(s.t) + "</button></li>").join("") + '</ol><span class="zx-rp-count"></span></div>' +
      '<div class="zx-rp-card"><div class="zx-rp-from"></div><div class="zx-pan sent"><h5>You run</h5><pre></pre></div><p class="zx-rp-q"></p>' +
      '<button type="button" class="zx-btn zx-rp-reveal"></button>' +
      '<div class="zx-rp-ans" hidden><div class="zx-pan back"><h5><span>It printed</span><button type="button" class="zx-rp-all"></button></h5><pre></pre></div><p class="zx-seq-note"></p><button type="button" class="zx-mini zx-rp-next"></button></div></div>';
    const chips = $$(".zx-seq-steps button", box), card = $(".zx-rp-card", box), from = $(".zx-rp-from", box), sent = $(".zx-pan.sent", box), q = $(".zx-rp-q", box), rv = $(".zx-rp-reveal", box), ans = $(".zx-rp-ans", box), back = $(".zx-pan.back", box), note = $(".zx-seq-note", box), nx = $(".zx-rp-next", box), allB = $(".zx-rp-all", box), count = $(".zx-rp-count", box);
    function short(s) { return (s.pre ? "…\n" : "") + s.out + (s.more > 0 && (!s.pre || s.tailOpen) ? "\n…" : ""); }
    function paint() { count.textContent = seen.size + " of " + steps.length + " revealed"; chips.forEach((b, k) => { b.classList.toggle("seen", seen.has(k)); if (k === i) b.setAttribute("aria-current", "step"); else b.removeAttribute("aria-current"); }); }
    function open(anim) {
      const s = steps[i]; seen.add(i); ans.hidden = false; rv.hidden = true;
      if (!s.plain) { $("pre", back).textContent = short(s); allB.hidden = s.more <= 0; allB.textContent = "Show all " + (s.more + s.out.split("\n").length) + " lines"; allB.dataset.open = ""; }
      note.innerHTML = ic(s.plain ? "check" : "eye") + "<span>" + s.a + "</span>";
      nx.innerHTML = i < steps.length - 1 ? "Next run" + ic("fwd") : ic("replay") + "Start again"; if (!runs) nx.innerHTML = i < steps.length - 1 ? "Next question" + ic("fwd") : ic("replay") + "Start again";
      if (anim && !Z.calm) ans.animate([{ opacity: 0, transform: "translateY(10px)" }, { opacity: 1, transform: "none" }], { duration: 380, easing: Z.EASE });
      paint();
    }
    function show(k, anim) {
      i = (k + steps.length) % steps.length; const s = steps[i];
      sent.hidden = back.hidden = !!s.plain; from.hidden = !!s.plain || !s.from;
      if (!s.plain) { $("pre", sent).innerHTML = hl(s.code, s.lang); from.innerHTML = 'From <button type="button" class="zx-rp-go">' + esc(s.from) + "</button>"; }
      q.innerHTML = '<span class="k">' + (s.plain ? "Question" : "Before you reveal") + "</span>" + s.q;
      rv.innerHTML = ic("eye") + (s.plain ? "Reveal the answer" : "Reveal the output"); rv.hidden = false; ans.hidden = true;
      if (seen.has(i)) open(false);
      if (anim && !Z.calm) card.animate([{ opacity: 0, transform: "translateX(14px)" }, { opacity: 1, transform: "none" }], { duration: 320, easing: Z.EASE });
      paint();
    }
    chips.forEach((b, k) => b.addEventListener("click", () => show(k, true)));
    rv.addEventListener("click", () => open(true));
    nx.addEventListener("click", () => { if (i === steps.length - 1) { seen.clear(); show(0, true); } else show(i + 1, true); });
    allB.addEventListener("click", () => { const s = steps[i], on = !allB.dataset.open; allB.dataset.open = on ? "1" : ""; $("pre", back).textContent = on ? s.full : short(s); allB.textContent = on ? "Show less" : "Show all " + s.full.split("\n").length + " lines"; });
    from.addEventListener("click", e => { if (e.target.closest(".zx-rp-go") && steps[i].si >= 0 && Z.go) Z.go(L, steps[i].si); });
    body.appendChild(box); show(0, false);
  }
  /* the last part: every "In one line" of the lesson, to recall before leaving */
  function carry(L, wrap) {
    const done = $('.zx-stage[data-kind="done"] .zx-done', wrap); if (!done || $(".zx-carry", done)) return;
    const items = $$(".zx-take", wrap).map(t => { const st = t.closest(".zx-stage"); return { h: st ? ($(".zx-stage-title", st) || {}).textContent || "" : "", t: $("p", t).innerHTML }; }).filter(x => x.h);
    if (items.length < 2) return;
    const box = el("div", "zx-carry zx-ui"); box.innerHTML = '<div class="zx-carry-head"><h3>Carry forward</h3><button type="button" class="zx-mini zx-carry-all">Show all</button></div><p>For each part, say its main point from memory. Then tap to check.</p><ol>' +
      items.map(x => '<li><button type="button" aria-expanded="false"><span class="h">' + esc(x.h) + '</span><span class="t">' + x.t + "</span></button></li>").join("") + "</ol>";
    box.addEventListener("click", e => { const all = e.target.closest(".zx-carry-all"), b = e.target.closest("li > button"); if (all) { const on = all.textContent === "Show all"; $$("li > button", box).forEach(x => x.setAttribute("aria-expanded", on)); all.textContent = on ? "Hide all" : "Show all"; } else if (b) b.setAttribute("aria-expanded", b.getAttribute("aria-expanded") !== "true"); });
    const foot = $("footer.m-foot", done); if (foot) foot.before(box); else done.appendChild(box);
  }
  const problems = [];
  return { has: has, build: build, hash: hash, problems: problems };
})();

